const grouped = (): TableData => {
  let t = newGroupedTable(2, 3); // A:Y1 A:Y2 A:Y3 B:Y1 B:Y2 B:Y3
  t = writeBlock(t, 0, 0, [["r1", "a1", "a2", "a3", "b1", "b2", "b3"]], "grouped");
  t = renameGroup(t, "B", "Treated");
  return { ...t, excluded: ["0,4"] }; // Treated:Y1
};

const treatments = (columns: string[]): TableData => ({
  columns: ["Title", ...columns],
  rows: [1, 2, 3].map((r) => [null, ...columns.map((_, c) => String(r + c))]),
});

// ── Paste Special / Transpose (seq 230) + Select Row/Column (seq 231) ──────
// 231's selection is the grid's Shift+Space / Ctrl+Space behavior with a menu
// name on it, so its pin is the range the keys build (whole rows / whole
// columns of the selection); 230's pin is the transpose itself, plus the
// transposed block landing where Paste would put it.

check("transposing a block swaps rows and columns, pads ragged rows, and transposes back", () => {
  const block = [
    ["a", "b", "c"],
    ["d", "e"],
  ];
  deepStrictEqual(transposeBlock(block), [
    ["a", "d"],
    ["b", "e"],
    ["c", null],
  ]);
  deepStrictEqual(transposeBlock(transposeBlock(block)), [
    ["a", "b", "c"],
    ["d", "e", null],
  ]);
  deepStrictEqual(transposeBlock([["x"]]), [["x"]]);
  deepStrictEqual(transposeBlock([]), []);
});

check("a transposed block pastes at the selection's top-left, growing the table", () => {
  const t = newTable("xy", 2);
  const pasted = writeBlock(t, 0, 0, transposeBlock([["r1", "r2"], ["1", "2"]]), "xy");
  strictEqual(pasted.rows[0][0], "r1");
  strictEqual(pasted.rows[1][0], "r2");
  strictEqual(pasted.rows[0][1], "1");
  strictEqual(pasted.rows[1][1], "2");
});

// ── Paste Special digit + legacy-format options (seq 428) ───────────────
// Prism's Import and Paste Special Choices, Source tab (walk2/07): two
// checkboxes Titer's Paste Special (seq 230, Values / Transpose only) never
// offered — "Paste as many digits as possible. If Excel rounds to 1.23
// paste 1.23456." and "Paste older text-based clipboard format. Not
// recommended." Per the Prism 11 guide ("Options when pasting data from
// Excel") and FAQ 1534: Excel copies in two formats, plain text and HTML;
// Prism pastes the HTML one by default (the values as shown in Excel),
// the older text one pastes the full values, and the HTML copy from older
// Excel carries each number twice — shown and full-precision (x:num) —
// which the many-digits option selects.
const EXCEL_HTML_428 =
  '<html><body><table>' +
  '<tr><td x:num="1.23456">1.23</td><td x:num="2.5">2.50</td><td>label</td></tr>' +
  '<tr><td x:num="10">10</td><td>&nbsp;</td><td><b>bold</b> text</td></tr>' +
  "</table></body></html>";

check("paste-428: Paste Special offers Prism's digit + legacy-format options", () => {
  // The HTML clipboard parses to the values as shown in Excel; the
  // many-digits option takes the full-precision x:num copy instead.
  deepStrictEqual(parseClipboardHTML(EXCEL_HTML_428, false), [
    ["1.23", "2.50", "label"],
    ["10", null, "bold text"],
  ]);
  deepStrictEqual(parseClipboardHTML(EXCEL_HTML_428, true), [
    ["1.23456", "2.5", "label"],
    ["10", null, "bold text"],
  ]);
  // A cell with no x:num keeps its shown text either way; HTML with no
  // table in it is not a pasteable block.
  deepStrictEqual(parseClipboardHTML("<p>no table here</p>", true), []);
  deepStrictEqual(parseClipboardHTML(EXCEL_HTML_428.replace(' x:num="2.5"', ""), true), [
    ["1.23456", "2.50", "label"],
    ["10", null, "bold text"],
  ]);

  // Format choice: the older text format parses the plain text even when
  // HTML is on the clipboard; otherwise the HTML copy wins; with no HTML
  // the text is all there is.
  const text428 = "9.99\t8.88\n7.77\t";
  deepStrictEqual(
    pasteSpecialBlock(EXCEL_HTML_428, text428, { olderTextFormat: true, manyDigits: true }),
    [
      ["9.99", "8.88"],
      ["7.77", null],
    ],
  );
  deepStrictEqual(
    pasteSpecialBlock(EXCEL_HTML_428, text428, { olderTextFormat: false, manyDigits: true }),
    [
      ["1.23456", "2.5", "label"],
      ["10", null, "bold text"],
    ],
  );
  deepStrictEqual(
    pasteSpecialBlock(null, text428, { olderTextFormat: false, manyDigits: true }),
    [
      ["9.99", "8.88"],
      ["7.77", null],
    ],
  );

  // Many digits must be visible: pasting with the option on clears the
  // decimal-places display setting on the pasted data columns (never the
  // title column), so the extra digits aren't rounded away on screen.
  const t428: TableData = { columns: ["Title", "A", "B"], rows: [] };
  const withDecimals = setDecimalPlaces(setDecimalPlaces(t428, "A", 2), "B", 4);
  deepStrictEqual(clearDecimalsForRange(withDecimals, 1, 2).decimals, undefined);
  deepStrictEqual(clearDecimalsForRange(withDecimals, 1, 1).decimals, { B: 4 });
  deepStrictEqual(clearDecimalsForRange(withDecimals, 0, 1).decimals, { A: 2, B: 4 });

  // The dialog itself carries both options, worded as Prism words them.
  const grid428 = readFileSync("src/views/tables/grid.tsx", "utf8");
  ok(grid428.includes("Paste as many digits as possible"), "Paste Special must offer Prism's many-digits option");
  ok(grid428.includes("Paste older text-based clipboard format"), "Paste Special must offer Prism's older-text option");
  ok(
    grid428.includes("olderTextFormat") && grid428.includes("manyDigits"),
    "Paste Special must carry both options in its offer state",
  );
});

check("paste-439: Paste Special reads the clipboard natively, not via the webview", () => {
  // The Mac proof batch (post-1.9.0, tip 5e40885) showed Edit > Paste
  // Special… always alerts "Nothing to Paste": navigator.clipboard.read()
  // needs transient user activation in the page, and a native menu-bar
  // action never gives the page any — so the read can never succeed from
  // that entry point, for real users as well as synthetic input. The fix
  // is a Rust-side read (seq 439), mirroring the seq 296 write workaround.
  const mainRs = readFileSync("src-tauri/src/main.rs", "utf8");
  ok(mainRs.includes("read_clipboard_formats"), "main.rs must define the read_clipboard_formats command");
  ok(
    mainRs.includes("fn read_clipboard_formats") && mainRs.includes("#[tauri::command]"),
    "read_clipboard_formats must be a Tauri command",
  );
  ok(
    mainRs.includes("read_clipboard_formats,") || mainRs.includes("\n            read_clipboard_formats"),
    "read_clipboard_formats must be registered in the invoke handler",
  );
  // The native read must return both formats Paste Special needs: the
  // plain text and the HTML table (Excel's x:num digits live in the HTML).
  // Seq 444: the HTML flavour must be requested by its full UTI
  // `public.html` — `pbpaste -Prefer html` returns PLAIN TEXT on macOS
  // (verified twice by the post-1.9.0 proof batch), so the old bare name
  // left the html field holding TSV and the many-digits option could
  // never fire.
  ok(
    mainRs.includes("pbpaste") && mainRs.includes('"-Prefer", "public.html"'),
    "the native read must use pbpaste, with -Prefer public.html for the HTML flavour",
  );
  ok(
    mainRs.includes("text:") && mainRs.includes("html:"),
    "the native read must return both a text and an html form",
  );

  // The page reaches it through native.ts, like the seq 296 write.
  const native = readFileSync("src/native.ts", "utf8");
  ok(native.includes("export async function readClipboardFormats"), "native.ts must export readClipboardFormats");
  ok(
    native.includes('invoke<') && native.includes('"read_clipboard_formats"'),
    "readClipboardFormats must invoke the read_clipboard_formats command",
  );

  // The grid tries the native read FIRST, before the webview read — the
  // menu-triggered flow must no longer depend solely on
  // navigator.clipboard.read(), which can never succeed from a menu bar.
  const grid439 = readFileSync("src/views/tables/grid.tsx", "utf8");
  ok(
    grid439.includes("readClipboardFormatsNative()"),
    "grid.tsx must call the native clipboard read (readClipboardFormatsNative)",
  );
  const nativeCall = grid439.indexOf("readClipboardFormatsNative()");
  const webviewRead = grid439.indexOf("navigator.clipboard.read()");
  ok(
    nativeCall !== -1 && webviewRead !== -1 && nativeCall < webviewRead,
    "the native read must be attempted before the webview read in grid.tsx",
  );
  ok(
    grid439.indexOf("readClipboardText") !== -1,
    "readClipboardText must still exist as the text fallback",
  );
});

check("paste-444: the native clipboard read must ask pbpaste for public.html, not html", () => {
  // The post-1.9.0 Mac proof batch showed Paste Special's "Paste as many
  // digits as possible" never fires: read_clipboard_formats asked for the
  // HTML flavour with `pbpaste -Prefer html`, and on macOS that returns
  // PLAIN TEXT, not HTML — so the html field always held TSV and the
  // x:num full-precision values were never there to take. Only the full
  // UTI `public.html` returns the real HTML table. The bare name must not
  // come back: a future edit reintroducing it would silently break the
  // digits option again with no error anywhere.
  const mainRs = readFileSync("src-tauri/src/main.rs", "utf8");
  ok(
    mainRs.includes('"-Prefer", "public.html"'),
    "read_clipboard_formats must request the HTML flavour as public.html",
  );
  ok(
    !mainRs.includes('"-Prefer", "html"'),
    "read_clipboard_formats must not request the HTML flavour as bare html (pbpaste returns plain text for that)",
  );
  // The doc comment above the command must say public.html too, so the
  // next reader doesn't "fix" it back to the bare name.
  ok(
    mainRs.includes("pbpaste -Prefer public.html"),
    "the read_clipboard_formats doc comment must name pbpaste -Prefer public.html",
  );
});

