// ROUT-in-fit (v2, upstream 1.0.9): a gross outlier in a 4PL dose-response
// fit is flagged by ROUT, left out of the fit, and reported — the fit then
// recovers the clean curve, where the rout-off fit is pulled 11× off it.
// (Reference values from WebR: clean EC50 0.14389, corrupted rout-off 1.632,
// corrupted rout-on 0.14362.)
check("ROUT leaves a flagged outlier out of a 4PL fit and the fit recovers the clean curve", async () => {
  const doseLog: TableData = {
    columns: ["Title", "X", "Response"],
    rows: [
      ["", "-3", "2.1"],
      ["", "-2.5", "3.4"],
      ["", "-2", "8.2"],
      ["", "-1.5", "19.5"],
      ["", "-1", "41.2"],
      ["", "-0.5", "68.9"],
      ["", "0", "86.1"],
      ["", "0.5", "94.2"],
      ["", "1", "97.8"],
      ["", "1.5", "99.1"],
    ],
  };
  const corrupted: TableData = {
    ...doseLog,
    rows: doseLog.rows.map((r) => (r[1] === "0" ? ["", "0", "20"] : r)),
  };
  const clean = await runAnalysis("nonlinear-regression", doseLog, { model: "sigmoidal-4pl-logx" });
  ok(!("error" in clean) && clean.coefficients);
  const cleanEC50 = clean.fit?.rows.find((r) => r.label === "EC50")?.values?.[0];
  ok(cleanEC50 != null && Math.abs(cleanEC50 - 0.14389) < 0.002);
  const off = await runAnalysis("nonlinear-regression", corrupted, { model: "sigmoidal-4pl-logx" });
  ok(!("error" in off) && off.coefficients);
  const offEC50 = off.fit?.rows.find((r) => r.label === "EC50")?.values?.[0];
  ok(offEC50 != null && Math.abs(offEC50 - 1.632) < 0.01);
  const on = await runAnalysis("nonlinear-regression", corrupted, { model: "sigmoidal-4pl-logx", rout: true });
  ok(!("error" in on) && on.coefficients);
  // Exactly the corrupted point is flagged, with its table position.
  deepStrictEqual(on.curveOutliers, [{ set: "Response", label: "Row 7", x: 0, y: 20, key: "Response#6" }]);
  deepStrictEqual(on.fit?.rows.find((r) => r.label === "Outliers (ROUT)")?.values, [1]);
  strictEqual(on.fit?.rows.find((r) => r.label === "N")?.values?.[0], 9);
  const onEC50 = on.fit?.rows.find((r) => r.label === "EC50")?.values?.[0];
  ok(onEC50 != null && Math.abs(onEC50 - 0.14362) < 0.002);
  // The rout-on fit recovers the clean curve; the rout-off fit does not.
  ok(onEC50 != null && cleanEC50 != null && offEC50 != null);
  ok(Math.abs(onEC50 - cleanEC50) < Math.abs(offEC50 - cleanEC50));
  ok(on.notes.includes("Outliers found by ROUT (Q = 1%"));
  // A Q outside 0.01–50 is refused before R runs.
  deepStrictEqual(
    await runAnalysis("nonlinear-regression", corrupted, { model: "sigmoidal-4pl-logx", rout: true, q: 60 }),
    { error: "Q must be between 0.01 and 50." },
  );
});

// ROUT-in-fit (v2, upstream 1.0.9): the global fit finds each series'
// outliers on its own fit, and a line (lm) fit's ROUT works through the
// same wrapper — both recover the clean curve. (Reference values from WebR:
// global EC50 0.14377 shared; line slope 2.0 with ROUT, 3.393 without.)
check("ROUT excludes outliers per series in a global fit, and from a line fit", async () => {
  const ys = ["2.1", "3.4", "8.2", "19.5", "41.2", "68.9", "86.1", "94.2", "97.8", "99.1"];
  const xs = ["-3", "-2.5", "-2", "-1.5", "-1", "-0.5", "0", "0.5", "1", "1.5"];
  const globalTable: TableData = {
    columns: ["Title", "X", "A", "B"],
    rows: xs.map((x, i) => ["", x, ys[i], i === 6 ? "20" : ys[i]]),
  };
  const g = await runAnalysis("nonlinear-regression", globalTable, {
    model: "sigmoidal-4pl-logx",
    globalY: ["B"],
    rout: true,
  });
  ok(!("error" in g) && g.coefficients);
  // Both corrupted points are flagged: B's (Row 7) and A's own largest
  // residual (Row 6, the mid-curve point) — upstream 1.1.0's ROUT takes the
  // RSDR at R's default quantile (type 7, "what gives Prism's outliers"),
  // whose smaller scale flags it where the old type-6 RSDR did not.
  deepStrictEqual(g.curveOutliers, [
    { set: "A", label: "Row 6", x: -0.5, y: 68.9, key: "A#5" },
    { set: "B", label: "Row 7", x: 0, y: 20, key: "B#6" },
  ]);
  deepStrictEqual(g.fit?.rows.find((r) => r.label === "Outliers (ROUT)")?.values, [1, 1]);
  deepStrictEqual(g.fit?.rows.find((r) => r.label === "N")?.values, [9, 9]);
  const ec50 = g.fit?.rows.find((r) => r.label === "EC50")?.values;
  ok(ec50?.length === 2 && ec50.every((v) => v != null && Math.abs(v - 0.14377) < 0.002));
  ok(g.notes.includes("Outliers found by ROUT (Q = 1%"));
  // A line fit's ROUT: the same wrapper, an lm fit — slope 2, not the
  // outlier-pulled 3.39.
  const lineTable: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["", "0", "1"],
      ["", "1", "3"],
      ["", "2", "5"],
      ["", "3", "7"],
      ["", "4", "9"],
      ["", "5", "50"],
      ["", "6", "13"],
      ["", "7", "15"],
    ],
  };
  const l = await runAnalysis("nonlinear-regression", lineTable, { y: "Y1", model: "line", rout: true });
  ok(!("error" in l) && l.coefficients);
  deepStrictEqual(l.curveOutliers, [{ set: "Y1", label: "Row 6", x: 5, y: 50, key: "Y1#5" }]);
  deepStrictEqual(l.fit?.rows.find((r) => r.label === "Outliers (ROUT)")?.values, [1]);
  strictEqual(l.fit?.rows.find((r) => r.label === "N")?.values?.[0], 7);
  const slope = l.coefficients?.find((c) => c.term === "Slope")?.estimate;
  ok(slope != null && Math.abs(slope - 2) < 0.001);
  const lOff = await runAnalysis("nonlinear-regression", lineTable, { y: "Y1", model: "line" });
  ok(!("error" in lOff) && lOff.coefficients);
  const offSlope = lOff.coefficients?.find((c) => c.term === "Slope")?.estimate;
  ok(offSlope != null && Math.abs(offSlope - 3.393) < 0.01);
});

// R2-m10: band inversion on a non-monotonic standard curve can return an
// inverted 95% CI (low > high), which reads as a valid interval. An
// inverted-U quadratic (Y = −x² + 6x over X 0..7, noisy so the band has
// width) with an unknown Y = 5 on the rising limb inverts on unfixed code
// (low 1.096 > high 0.847): the fix drops the CI and says so in the notes,
// keeping the point estimate.
check("an inverted band-inversion CI is dropped, never shown as an interval", async () => {
  const xs = [0, 1, 2, 3, 4, 5, 6, 7];
  const noise = [0.3, -0.2, 0.4, -0.3, 0.2, -0.4, 0.3, -0.2];
  const quad: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ...xs.map((x, i) => ["", String(x), String(-x * x + 6 * x + noise[i])]),
      ["", "", "5"],
    ],
  };
  const out = await runAnalysis("nonlinear-regression", quad, { y: "Y1", model: "quadratic", interpolate: true });
  ok(!("error" in out) && out.interpolated?.length === 1);
  const u = out.interpolated[0];
  ok(u.x != null && Math.abs(u.x - 0.973) < 0.01);
  strictEqual(u.low, null);
  strictEqual(u.high, null);
  ok(!("error" in out) && out.notes.includes("comes back inverted"));
});

// BUG-REPORT #9 (FL-R3-09): a smoothing spline on an XY table with tied X
// values failed outright — smooth.spline's fit$y lives on the UNIQUE sorted
// knots (length(unique(x))), so the old code returned 4 + 100 values for 5
// observations and R recycled fit$y across mismatched rows in the RSS.
// fitted(fit) is per-observation, so the fit now returns one fitted value
// per row and the RSS is sum((y - fitted(fit))^2). Reference values below
// are smooth.spline(x, y) on X = [1,1,2,3,4], Y = [2,2.5,4,6,8], computed
// straight from R (spar 1.4805142007968894, df 2.00000000833144).
check("a smoothing spline fits tied X values, one fitted value per observation (FL-R3-09)", async () => {
  const table: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["", "1", "2"],
      ["", "1", "2.5"],
      ["", "2", "4"],
      ["", "3", "6"],
      ["", "4", "8"],
    ],
  };
  const out = await runAnalysis("spline-lowess", table, { method: "spline" } as never);
  if ("error" in out) throw new Error(out.error);
  const expected = [2.2058824056037776, 2.2058824056037776, 4.117646984179642, 6.029411567068956, 7.941176153346085];
  strictEqual(out.fitted?.length, 5);
  strictEqual(out.curve?.length, 100);
  out.fitted!.forEach((p, i) => ok(Math.abs(p.y - expected[i]) < 1e-9, `fitted[${i}]`));
  // The tied X = 1 rows share one knot but are two observations: both get
  // the knot's fitted value, and the residuals use each row's own Y.
  strictEqual(out.fitted![0].y, out.fitted![1].y);
  const rss = out.stats.find((s) => s.label === "Residual sum of squares")?.value;
  ok(rss != null && Math.abs(rss - 0.14705882236979922) < 1e-9, `rss ${rss}`);
  // The reported RSS agrees with the fitted values it ships: recomputed
  // in TS from the residuals, so a recycled fit$y cannot hide in it.
  const recomputed = out.fitted!.reduce((sum, p) => sum + (p.observed! - p.y) ** 2, 0);
  ok(rss != null && Math.abs(recomputed - rss) < 1e-9, `recomputed rss ${recomputed}`);
  const spar = out.stats.find((s) => s.label === "Smoothing parameter (spar)")?.value;
  ok(spar != null && Math.abs(spar - 1.4805142007968894) < 1e-9, `spar ${spar}`);
  // Fewer than 4 DISTINCT X values is rejected cleanly before R runs,
  // instead of surfacing R's "need at least four unique 'x' values".
  const few: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["", "1", "2"],
      ["", "1", "2.5"],
      ["", "2", "4"],
      ["", "3", "6"],
      ["", "3", "7"],
    ],
  };
  deepStrictEqual(await runAnalysis("spline-lowess", few, { method: "spline" } as never), {
    error: "A smoothing spline needs at least 4 distinct X values.",
  });
});

// Smooth, differentiate or integrate a curve (v2): Savitzky–Golay smoothing,
// a first or second numerical derivative, or a cumulative integral — each a
// NEW curve table per Y data set (Prism's Analyse → Smooth, Differentiate or
// Integrate a Curve). The pure maths is pinned directly; the runner pins go
// through runAnalysis like every other analysis.
check("Savitzky–Golay coefficients match the published window-5 values and reproduce a quadratic", () => {
  const w5 = savitzkyGolayCoefficients(5, 3);
  const expected = [-3, 12, 17, 12, -3].map((c) => c / 35);
  strictEqual(w5.length, 5);
  w5.forEach((c, i) => ok(Math.abs(c - expected[i]) < 1e-12, `w5[${i}] ${c}`));
  // Orders 2 and 3 coincide for a symmetric window (the odd terms vanish).
  deepStrictEqual(savitzkyGolayCoefficients(5, 2), w5);
  // Smoothing y = x² reproduces x² exactly at interior points (order ≥ 2
  // is invariant on a quadratic) — and the edge rows are dropped, counted.
  const xs = [0, 1, 2, 3, 4, 5, 6];
  const out = smoothValues(xs, xs.map((x) => x * x), 5, 3);
  deepStrictEqual(out.x, [2, 3, 4]);
  out.y.forEach((y, i) => ok(Math.abs(y - out.x[i] ** 2) < 1e-9, `smoothed[${i}] ${y}`));
  strictEqual(out.dropped, 4);
  // Window-5 smoothing of [1,2,1,2,1,2,1]: the first window's centre is 59/35.
  const alt = smoothValues([0, 1, 2, 3, 4, 5, 6], [1, 2, 1, 2, 1, 2, 1], 5, 3);
  ok(Math.abs(alt.y[0] - 59 / 35) < 1e-12, `centre ${alt.y[0]}`);
  strictEqual(equallySpaced([0, 1, 2, 3]), true);
  strictEqual(equallySpaced([0, 1, 3]), false);
});

check("first and second derivatives follow Prism's forward-difference algorithm, and the integral the trapezoid rule", () => {
  const d1 = firstDerivative([0, 1, 2, 3], [0, 1, 4, 9]);
  deepStrictEqual(d1.x, [0.5, 1.5, 2.5]);
  deepStrictEqual(d1.y, [1, 3, 5]);
  const d2 = secondDerivative([0, 1, 2, 3], [0, 1, 4, 9]);
  deepStrictEqual(d2.x, [1, 2]);
  deepStrictEqual(d2.y, [2, 2]);
  deepStrictEqual(cumulativeIntegral([0, 1, 2], [0, 2, 4], 0, 0).y, [0, 1, 4]);
  deepStrictEqual(cumulativeIntegral([0, 1, 2], [0, 2, 4], 2, 0).y, [0, -1, 0]);
});

check("smooth, differentiate or integrate a curve returns a new curve table per data set", async () => {
  const table: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["", "0", "0"],
      ["", "1", "1"],
      ["", "2", "4"],
      ["", "3", "9"],
      ["", "4", "16"],
      ["", "5", "25"],
      ["", "6", "36"],
    ],
  };
  const smooth = await runAnalysis("smooth-differentiate-integrate", table, {
    operation: "smooth",
    window: 5,
    order: 3,
  });
  if ("error" in smooth) throw new Error(smooth.error);
  strictEqual(smooth.derivedCurves?.length, 1);
  deepStrictEqual(smooth.derivedCurves![0].x, [2, 3, 4]);
  smooth.derivedCurves![0].y.forEach((y, i) =>
    ok(Math.abs(y - smooth.derivedCurves![0].x[i] ** 2) < 1e-9, `smoothed[${i}] ${y}`),
  );
  strictEqual(smooth.derivedCurves![0].dropped, 4);
  strictEqual(smooth.stats.find((s) => s.label === "Smoothed(Y1) — N")?.value, 3);
  strictEqual(smooth.stats.find((s) => s.label === "Smoothed(Y1) — rows dropped")?.value, 4);

  const deriv = await runAnalysis("smooth-differentiate-integrate", table, { operation: "first-derivative" });
  if ("error" in deriv) throw new Error(deriv.error);
  deepStrictEqual(deriv.derivedCurves![0].x, [0.5, 1.5, 2.5, 3.5, 4.5, 5.5]);
  deepStrictEqual(deriv.derivedCurves![0].y, [1, 3, 5, 7, 9, 11]);
  strictEqual(deriv.derivedCurves![0].dropped, 1);

  const deriv2 = await runAnalysis("smooth-differentiate-integrate", table, { operation: "second-derivative" });
  if ("error" in deriv2) throw new Error(deriv2.error);
  deepStrictEqual(deriv2.derivedCurves![0].x, [1, 2, 3, 4, 5]);
  deepStrictEqual(deriv2.derivedCurves![0].y, [2, 2, 2, 2, 2]);
  strictEqual(deriv2.derivedCurves![0].dropped, 2);

  const integral = await runAnalysis("smooth-differentiate-integrate", table, {
    operation: "integral",
    baseline: 0,
    startValue: 0,
  });
  if ("error" in integral) throw new Error(integral.error);
  deepStrictEqual(integral.derivedCurves![0].x, [0, 1, 2, 3, 4, 5, 6]);
  deepStrictEqual(integral.derivedCurves![0].y, [0, 0.5, 3, 9.5, 22, 42.5, 73]);
  strictEqual(integral.derivedCurves![0].dropped, 0);
  // The source table is unchanged — the derived curve lives in the result only.
  strictEqual(table.rows.length, 7);
});

check("smooth, differentiate or integrate a curve names its failures", async () => {
  // Uneven X + smoothing: Savitzky–Golay needs a uniform grid.
  const uneven: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["", "0", "0"],
      ["", "1", "1"],
      ["", "3", "9"],
      ["", "4", "16"],
      ["", "5", "25"],
      ["", "6", "36"],
      ["", "7", "49"],
    ],
  };
  deepStrictEqual(
    await runAnalysis("smooth-differentiate-integrate", uneven, { operation: "smooth", window: 5, order: 3 }),
    { error: "“Y1” does not have equally spaced X values — Savitzky–Golay smoothing needs a uniform X grid." },
  );
  // Too few points for the window, and for a derivative.
  const few: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["", "0", "0"],
      ["", "1", "1"],
      ["", "2", "4"],
    ],
  };
  deepStrictEqual(
    await runAnalysis("smooth-differentiate-integrate", few, { operation: "smooth", window: 5, order: 3 }),
    { error: "“Y1” has only 3 points — smoothing with a window of 5 neighbours needs at least 5." },
  );
  const one: TableData = { columns: ["Title", "X", "Y1"], rows: [["", "0", "0"]] };
  deepStrictEqual(
    await runAnalysis("smooth-differentiate-integrate", one, { operation: "first-derivative" }),
    { error: "“Y1” has only 1 point — first derivative needs at least 2." },
  );
  // A named data set holding no numbers is named, not silently skipped.
  const empty: TableData = {
    columns: ["Title", "X", "Y1", "Y3"],
    rows: [
      ["", "0", "0", ""],
      ["", "1", "1", ""],
      ["", "2", "4", ""],
    ],
  };
  deepStrictEqual(
    await runAnalysis("smooth-differentiate-integrate", empty, { operation: "smooth", ys: ["Y3"], window: 5, order: 3 }),
    { error: "“Y3” holds no numbers yet." },
  );
  // Smoothing a derivative that came out shorter than the window is named,
  // not silently returned empty.
  const four: TableData = {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["", "0", "0"],
      ["", "1", "1"],
      ["", "2", "4"],
      ["", "3", "9"],
    ],
  };
  deepStrictEqual(
    await runAnalysis("smooth-differentiate-integrate", four, {
      operation: "first-derivative",
      smoothResults: true,
      window: 5,
      order: 3,
    }),
    { error: "“Y1” — after first derivative there are only 3 points, fewer than the 5 neighbours smoothing needs." },
  );
});

