check("styled points follow moved rows, renamed columns and groups, and leave with their column", () => {
  const styled = (
    points: Record<string, { size: number }>,
    columns: string[],
    move: Parameters<typeof followTable>[1],
  ) => followTable({ ...graph, graphOptions: { ...graph.graphOptions!, points } }, move, columns).graphOptions!.points;
  const points = { "Y1#0": { size: 1 }, "Y1#3": { size: 2 } };
  deepStrictEqual(styled(points, ["Title", "Y1"], { rows: rowsInserted(1, 2) }), {
    "Y1#0": { size: 1 },
    "Y1#5": { size: 2 },
  });
  deepStrictEqual(styled(points, ["Title", "Y1"], { rows: rowsDeleted(0, 1) }), { "Y1#2": { size: 2 } });
  deepStrictEqual(styled(points, ["Title", "Dose"], { renamed: { Y1: "Dose" } }), {
    "Dose#0": { size: 1 },
    "Dose#3": { size: 2 },
  });
  deepStrictEqual(styled({ "A:Y1#1": { size: 3 } }, ["Title", "Ctrl:Y1"], { renamed: { A: "Ctrl" } }), {
    "Ctrl:Y1#1": { size: 3 },
  });
  strictEqual(styled(points, ["Title", "Y2"], {}), undefined); // its column was deleted
});

check("deleting a column drops its points' styles, even with no move given", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  const data: TableData = { columns: ["Title", "A", "B"], rows: [[null, "1", "2"]] };
  s = reducer(s, { type: "updateTable", id: tableId, data, label: "Typing" });
  const g = {
    ...graph,
    id: "g9",
    parentId: tableId,
    graphOptions: { ...graph.graphOptions!, points: { "A#0": { size: 9 }, "B#0": { size: 9 } } },
  };
  s = reducer(s, { type: "create", node: g });
  s = reducer(s, {
    type: "updateTable",
    id: tableId,
    data: { columns: ["Title", "A"], rows: [[null, "1"]] },
    label: "Delete Column",
  });
  deepStrictEqual(s.nodes.g9.graphOptions!.points, { "A#0": { size: 9 } });
});

check("a floating note's edits undo as one change, and clearing them drops the field", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  const first = [{ id: "n1", text: "first", color: "yellow" as const, x: 10, y: 20 }];
  const second = [{ id: "n1", text: "second", color: "pink" as const, x: 10, y: 20 }];
  s = reducer(s, { type: "updateFloatingNotes", id: tableId, notes: first, at: 1000 });
  deepStrictEqual(s.nodes[tableId].floatingNotes, first);
  // A quick second edit (typing, recoloring) merges with the first in Undo.
  s = reducer(s, { type: "updateFloatingNotes", id: tableId, notes: second, at: 1500 });
  deepStrictEqual(s.nodes[tableId].floatingNotes, second);
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes[tableId].floatingNotes, undefined);
  // Deleting the last note leaves no empty field behind.
  s = reducer(s, { type: "updateFloatingNotes", id: tableId, notes: first, at: 3000 });
  s = reducer(s, { type: "updateFloatingNotes", id: tableId, notes: [], at: 4000 });
  strictEqual("floatingNotes" in s.nodes[tableId], false);
});

check("a sheet highlight's edits undo, and clearing it drops the field", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  s = reducer(s, { type: "setHighlight", id: tableId, highlight: "red" });
  strictEqual(s.nodes[tableId].highlight, "red");
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes[tableId].highlight, undefined);
  // Re-highlighting, then clearing, leaves no empty field behind.
  s = reducer(s, { type: "setHighlight", id: tableId, highlight: "blue" });
  s = reducer(s, { type: "setHighlight", id: tableId, highlight: null });
  strictEqual("highlight" in s.nodes[tableId], false);
  // Setting the color it already has is a no-op, not a new Undo step.
  s = reducer(s, { type: "setHighlight", id: tableId, highlight: "green" });
  const before = s;
  s = reducer(s, { type: "setHighlight", id: tableId, highlight: "green" });
  strictEqual(s, before);
});

