check("a Parts-of-Whole stacked bar stacks the categories in each data set", () => {
  const mendel = {
    columns: ["Title", "# of seeds", "Expected"],
    rows: [
      ["Round and yellow", "315", "312.75"],
      ["Round and green", "108", "104.25"],
      ["Angular and yellow", "101", "104.25"],
      ["Angular and green", "32", "34.75"],
    ],
  };
  const dataset = readTable(mendel);
  const options = { ...newGraphOptions("pow-stacked"), stackAs: "percent" as const };
  const fig = GRAPHS["pow-stacked"].build(dataset.numeric, options, paintOf(options, 4), dataset.titles);
  const traces = fig.data as { name?: string; x?: string[]; y?: (number | null)[] }[];
  // One trace per category (row), one bar per data set (column).
  deepStrictEqual(
    traces.map((t) => t.name),
    ["Round and yellow", "Round and green", "Angular and yellow", "Angular and green"],
  );
  deepStrictEqual(traces[0].x, ["# of seeds", "Expected"]);
  // Each bar's segments make 100 % (both data sets total 556).
  for (let b = 0; b < 2; b++) {
    const total = traces.reduce((s, t) => s + (t.y?.[b] ?? 0), 0);
    ok(Math.abs(total - 100) < 1e-9, `bar ${b} sums to ${total}, not 100`);
  }
  strictEqual((fig.layout as { barmode?: string }).barmode, "stack");
  strictEqual((fig.layout.yaxis as { title: { text: string } }).title.text, "Percent of total");
});

check("Match Another Graph… takes only what is ticked, series in order", () => {
  const graph = (type: GraphType, table: string, series: string[], over: Partial<GraphOptions>): Matched => ({
    type,
    table,
    series,
    options: { ...newGraphOptions(type), ...over },
  });
  const example = graph("mean-error", "t1", ["Vehicle", "Low", "High"], {
    pointSize: 12,
    yMax: 100,
    title: "Example",
    series: { Vehicle: { color: "#000000", shape: "diamond" }, High: { color: "#FF0000" } },
    points: { "Vehicle#0": { size: 15 } },
  });
  const target = graph("box-violin", "t2", ["A", "B"], { series: { A: { color: "#00FF00", dash: "dot" } } });
  const options = matched(target, example, ["points", "colors", "styled"]);
  strictEqual(options.pointSize, 12);
  deepStrictEqual(options.palette, example.options.palette);
  // By order: A takes Vehicle's color, B none (Low has none); A keeps its own dash.
  deepStrictEqual(options.series, { A: { color: "#000000", dash: "dot" } });
  // Unticked or out of reach: ranges, titles, and points styled in another table.
  deepStrictEqual([options.yMax, options.title, options.points], [undefined, "", undefined]);
  ok(matched({ ...target, table: "t1" }, example, ["styled"]).points);
  // A heatmap keeps its gradient when the example's palette is categorical.
  const heat = graph("heatmap", "t2", [], {});
  deepStrictEqual(matched(heat, example, ["colors"]).palette, heat.options.palette);
  // The examples: the other graphs Helix can draw, not one from a newer Helix.
  const child = (id: string): OutlineNode => ({ id, type: "graph", name: id, parentId: "t" });
  const tables = [
    { id: "t", type: "table" as const, name: "T", parentId: null, children: ["g1", "g2", "g3"].map(child) },
  ];
  const nodes = {
    g1: { ...child("g1"), graphType: "box-violin" },
    g2: { ...child("g2"), graphType: "mean-error" },
    g3: { ...child("g3"), graphType: "sankey" as GraphType }, // from a newer Helix
  } as Record<string, ProjectNode>;
  deepStrictEqual(examplesFor("g1", tables, nodes), [{ table: "T", graphs: [child("g2")] }]);
});

// Mansi P0 #7 (1.8 M6): Match shows a preview of what the new graph will look
// like — the target graph drawn with the matched options, live as the example
// and the ticked properties change.
check("Match preview draws the target graph with the matched options", () => {
  const data: TableData = {
    columns: ["Title", "WT:Y1", "WT:Y2", "WT:Y3", "SKG:Y1", "SKG:Y2", "SKG:Y3"],
    rows: [
      ["Day 1", "10", "12", "11", "20", "22", "21"],
      ["Day 2", "13", "14", "12", "24", "23", "25"],
    ],
    groups: 2,
    replicates: 3,
  };
  const table: ProjectNode = { id: "t", type: "table", name: "T", parentId: null, tableType: "grouped", data };
  const target: ProjectNode = {
    id: "g1",
    type: "graph",
    name: "Mine",
    parentId: "t",
    graphType: "grouped-scatter",
    graphOptions: newGraphOptions("grouped-scatter"),
  };
  const example: ProjectNode = {
    id: "g2",
    type: "graph",
    name: "Theirs",
    parentId: "t",
    graphType: "grouped-scatter",
    graphOptions: { ...newGraphOptions("grouped-scatter"), pointSize: 12, title: "Example" },
  };
  const nodes: Record<string, ProjectNode> = { t: table, g1: target, g2: example };
  const targetMatched = asMatched(target, nodes);
  const exampleMatched = asMatched(example, nodes);
  type Trace = { mode?: string; name?: string; marker?: { size?: number[] } };
  const pointsTrace = (fig: { data: unknown[] }) =>
    (fig.data as Trace[]).find((tr) => tr.mode === "markers" && tr.name === "WT");
  const titleOf = (fig: { layout: Record<string, unknown> }) =>
    (fig.layout.title as { text?: string } | undefined)?.text;

  // Nothing ticked: the preview is the graph as it is — no title, default point size.
  const plain = previewFigure(target, nodes, matched(targetMatched, exampleMatched, []));
  ok(plain, "the target graph has data to preview");
  strictEqual(titleOf(plain), undefined);
  ok(pointsTrace(plain)?.marker?.size?.every((s) => s === newGraphOptions("grouped-scatter").pointSize));

  // Points + titles ticked: the preview takes the example's point size and title.
  const previewOptions = matched(targetMatched, exampleMatched, ["points", "titles"]);
  const previewed = previewFigure(target, nodes, previewOptions);
  ok(previewed, "the matched graph has data to preview");
  strictEqual(titleOf(previewed), "Example");
  ok(pointsTrace(previewed)?.marker?.size?.every((s) => s === 12));
  // The preview is exactly the figure the matched options build — same traces, same layout.
  const dataset = readTable(data);
  const expected = GRAPHS["grouped-scatter"].build(
    plotColumns(dataset, "grouped-scatter", previewOptions, "grouped"),
    previewOptions,
    paintOf(previewOptions, 2),
    dataset.titles,
  );
  deepStrictEqual(previewed.data, expected.data);
  deepStrictEqual(previewed.layout, expected.layout);

  // Nothing to draw: an empty table previews nothing.
  const emptyTable: ProjectNode = {
    id: "te",
    type: "table",
    name: "Empty",
    parentId: null,
    tableType: "grouped",
    data: { columns: ["Title", "WT:Y1", "SKG:Y1"], rows: [["r1", "", ""]] },
  };
  const emptyGraph: ProjectNode = {
    id: "ge",
    type: "graph",
    name: "Empty graph",
    parentId: "te",
    graphType: "grouped-scatter",
    graphOptions: newGraphOptions("grouped-scatter"),
  };
  strictEqual(
    previewFigure(emptyGraph, { te: emptyTable, ge: emptyGraph }, newGraphOptions("grouped-scatter")),
    null,
  );
});

check("Batch Magic applies the ticked properties to many graphs at once, in one undo step", () => {
  const graph = (type: GraphType, table: string, series: string[], over: Partial<GraphOptions>): Matched => ({
    type,
    table,
    series,
    options: { ...newGraphOptions(type), ...over },
  });
  const example = graph("mean-error", "t1", ["Vehicle", "Low"], {
    pointSize: 12,
    series: { Vehicle: { color: "#000000" } },
  });
  const first = graph("box-violin", "t2", ["A", "B"], { series: { A: { color: "#00FF00" } } });
  const second = graph("mean-error", "t2", ["Vehicle"], {});
  // Already matches on BOTH ticked properties: the example's point size, its
  // palette, and its first series' color in order — so nothing would change.
  const already = graph("box-violin", "t2", ["A", "B"], {
    pointSize: 12,
    palette: example.options.palette,
    series: { A: { color: "#000000" } },
  });
  // A graph that would not change is left out (same gray-out as Match's toggles).
  const out = batchMatched(
    [
      { id: "g1", matched: first },
      { id: "g2", matched: second },
      { id: "g3", matched: already },
    ],
    example,
    ["points", "colors"],
  );
  deepStrictEqual(
    out.map((u) => u.id),
    ["g1", "g2"],
  );
  strictEqual(out[0].options.pointSize, 12);
  deepStrictEqual(out[0].options.series, { A: { color: "#000000" } });
  strictEqual(out[1].options.pointSize, 12);

  // One dispatch updates both graphs; one Undo takes both back.
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  s = reducer(s, {
    type: "create",
    node: { id: "g1", type: "graph", name: "First", parentId: tableId, graphType: "box-violin", graphOptions: first.options },
  });
  s = reducer(s, {
    type: "create",
    node: { id: "g2", type: "graph", name: "Second", parentId: tableId, graphType: "mean-error", graphOptions: second.options },
  });
  s = reducer(s, { type: "updateGraphs", updates: out, at: 1000 });
  strictEqual(s.nodes.g1.graphOptions?.pointSize, 12);
  strictEqual(s.nodes.g2.graphOptions?.pointSize, 12);
  ok(s.isDirty);
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes.g1.graphOptions?.pointSize, first.options.pointSize);
  strictEqual(s.nodes.g2.graphOptions?.pointSize, second.options.pointSize);
  // An unknown id (a graph deleted since the dialog opened) is skipped, not fatal.
  s = reducer(s, {
    type: "updateGraphs",
    updates: [...out, { id: "gone", options: out[0].options }],
    at: 2000,
  });
  strictEqual(s.nodes.g1.graphOptions?.pointSize, 12);
  strictEqual(s.nodes.gone, undefined);
});

check("a column graph's bars stand at their column, even with one-way error bars", () => {
  const table = {
    columns: ["Title", "A", "B", "C"],
    rows: [
      [null, "1", "2", "3"],
      [null, "2", "3", "4"],
    ],
  };
  for (const errorDirection of ["above", "both"] as const) {
    const options: GraphOptions = { ...newGraphOptions("mean-error"), errorDirection };
    const { data } = GRAPHS["mean-error"].build(readTable(table).numeric, options, paintOf(options, 3));
    // One offset group for every bar (and its caps' twin): Plotly sets none aside.
    deepStrictEqual(
      new Set(withCaps(data, options).map((t) => (t as { offsetgroup?: string }).offsetgroup)),
      new Set(["column"]),
    );
  }
});

check("error bars that go one way have no foot: their caps are at their tips alone", () => {
  type Trace = {
    type: string;
    y: number[];
    offsetgroup?: string;
    mode?: string;
    error_y?: { array: number[]; width: number };
  };
  const grouped = { columns: ["Title", "A:Y1", "A:Y2", "B:Y1", "B:Y2"], rows: [[null, "1", "3", "2", "6"]] };
  const above: GraphOptions = { ...newGraphOptions("grouped-bars"), errorDirection: "above", errorCaps: 8 };
  const built = GRAPHS["grouped-bars"].build(readTable(grouped).columns, above, paintOf(above, 2)).data;
  const [barA, capA, barB] = withCaps(built, above) as Trace[];
  strictEqual(barA.error_y!.width, 0); // the stem alone
  deepStrictEqual(
    [capA.type, capA.offsetgroup, barA.offsetgroup, capA.y, capA.error_y!.array, capA.error_y!.width],
    ["bar", "0", "0", [3], [0], 8],
  );
  strictEqual(barB.offsetgroup, "1");
  // Points' error bars get a twin of points; error bars both ways keep their caps.
  const points = { ...newGraphOptions("grouped-lines"), errorDirection: "above" as const };
  const [, twin] = withCaps(
    GRAPHS["grouped-lines"].build(readTable(grouped).columns, points, paintOf(points, 2)).data,
    points,
  ) as Trace[];
  strictEqual(twin.mode, "markers");
  const both = newGraphOptions("grouped-bars");
  const plain = GRAPHS["grouped-bars"].build(readTable(grouped).columns, both, paintOf(both, 2)).data;
  deepStrictEqual(withCaps(plain, both), plain);
  strictEqual((plain[0] as Trace).error_y!.width, 6);
});

