// ── Undo and names ───────────────────────────────────────────────────────

check("Undo and Redo take back and replay every kind of change", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  const empty = s.nodes[tableId].data!;
  const filled: TableData = { ...empty, rows: [[null, "1", "2"]] };
  s = reducer(s, { type: "updateTable", id: tableId, data: filled, label: "Typing" });
  s = reducer(s, { type: "rename", id: tableId, name: "Doses" });
  deepStrictEqual(
    s.past.map((step) => step.label),
    ["Typing", "Rename"],
  ); // "Undo Rename" in the Edit menu
  s = reducer(s, { type: "undo" });
  strictEqual(s.future.at(-1)?.label, "Rename"); // "Redo Rename"
  strictEqual(s.nodes[tableId].name, "Table 1");
  strictEqual(s.nodes[tableId].data, filled);
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes[tableId].data, empty);
  s = reducer(s, { type: "redo" });
  s = reducer(s, { type: "redo" });
  strictEqual(s.nodes[tableId].name, "Doses");
  strictEqual(s.future.length, 0);
});

check("new items are named among the names taken, and only ever in a table", () => {
  let s = makeInitialState(); // "Table 1"
  const table = (id: string): ProjectNode => ({
    id,
    type: "table",
    name: "Table",
    parentId: null,
    tableType: "column",
  });
  s = reducer(s, { type: "create", node: table("t2") });
  s = reducer(s, { type: "create", node: table("t3") });
  s = reducer(s, { type: "remove", id: "t2" });
  s = reducer(s, { type: "create", node: table("t4") });
  deepStrictEqual(
    s.rootOrder.map((id) => s.nodes[id].name),
    ["Table 1", "Table 3", "Table 2"],
  );
  s = reducer(s, { type: "create", node: { ...graph, id: "g2", parentId: "t3" } });
  s = reducer(s, { type: "create", node: { ...graph, id: "g3", parentId: "t3" } });
  deepStrictEqual(
    s.childOrder.t3.map((id) => s.nodes[id].name),
    ["Plot", "Plot 2"],
  );
  strictEqual(reducer(s, { type: "create", node: { ...graph, id: "g4", parentId: "g2" } }), s);
});

check("a deleted table comes back with its analyses and graphs", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  s = reducer(s, { type: "create", node: { ...analysis, parentId: tableId } });
  s = reducer(s, { type: "remove", id: tableId });
  // The analysis survives its table's deletion as an orphaned result (v2 item
  // 5) — only the table itself is gone.
  deepStrictEqual(Object.keys(s.nodes), [analysis.id]);
  strictEqual(s.nodes[analysis.id].orphaned, true);
  s = reducer(s, { type: "undo" });
  deepStrictEqual(Object.keys(s.nodes).sort(), [analysis.id, tableId].sort());
  deepStrictEqual(s.childOrder[tableId], [analysis.id]);
  strictEqual(s.nodes[analysis.id].orphaned, undefined);
});

// Frozen / orphaned results (v2 item 5): a minimal stored result, as the
// AnalysisView caches it after a successful live run.
const frozenResult: AnalysisResult = {
  testType: "linear-regression",
  stats: [{ label: "Slope", value: 2 }],
  groups: [],
  notes: "",
};

check("deleting a table keeps its analyses as orphaned results and deletes its graphs", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  // The node arrives with the result its view cached after a live run.
  s = reducer(s, { type: "create", node: { ...analysis, parentId: tableId, cachedResult: frozenResult } });
  s = reducer(s, { type: "create", node: { ...graph, parentId: tableId } });
  s = reducer(s, { type: "remove", id: tableId });
  // The graph is gone (its data is gone); the analysis survives, orphaned,
  // carrying the last computed result — Prism keeps orphaned results.
  strictEqual(s.nodes[graph.id], undefined);
  const orphan = s.nodes[analysis.id];
  ok(orphan, "the analysis must survive its table's deletion");
  strictEqual(orphan.orphaned, true);
  strictEqual(orphan.parentId, null);
  strictEqual(orphan.sourceTableName, "Table 1");
  deepStrictEqual(orphan.cachedResult, frozenResult);
  strictEqual(s.rootOrder.includes(analysis.id), true);
  strictEqual(s.childOrder[tableId], undefined);
  s = reducer(s, { type: "undo" });
  deepStrictEqual(Object.keys(s.nodes).sort(), [analysis.id, graph.id, tableId].sort());
  deepStrictEqual(s.childOrder[tableId], [analysis.id, graph.id]);
  strictEqual(s.nodes[analysis.id].orphaned, undefined);
});

check("an orphaned analysis survives a save and reload, with its frozen result", () => {
  const orphaned: ProjectNode = {
    ...analysis,
    parentId: null,
    orphaned: true,
    sourceTableName: "Doses",
    cachedResult: frozenResult,
  };
  const file = {
    nodes: { t1: table, a1: orphaned },
    rootOrder: ["t1", "a1"],
    childOrder: { t1: [] },
    activeNodeId: "a1",
  };
  const readBack = read(serializeProjectFile(file));
  strictEqual(readBack.updated, false);
  const kept = readBack.project.nodes.a1;
  ok(kept, "an orphaned analysis must survive a reload");
  strictEqual(kept.orphaned, true);
  strictEqual(kept.sourceTableName, "Doses");
  deepStrictEqual(kept.cachedResult, frozenResult);
  deepStrictEqual(readBack.project.rootOrder, ["t1", "a1"]);
});

check("freezing a results sheet keeps its cached result and stops it caching new ones", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  s = reducer(s, { type: "create", node: { ...analysis, parentId: tableId } });
  s = reducer(s, { type: "cacheAnalysisResult", id: analysis.id, result: frozenResult });
  deepStrictEqual(s.nodes[analysis.id].cachedResult, frozenResult);
  s = reducer(s, { type: "setAnalysisFrozen", id: analysis.id, frozen: true });
  strictEqual(s.nodes[analysis.id].frozen, true);
  // While frozen, a new live run is not cached (the view never runs one).
  const newer: AnalysisResult = {
    testType: "linear-regression",
    stats: [{ label: "Slope", value: 3 }],
    groups: [],
    notes: "",
  };
  s = reducer(s, { type: "cacheAnalysisResult", id: analysis.id, result: newer });
  deepStrictEqual(s.nodes[analysis.id].cachedResult, frozenResult);
  s = reducer(s, { type: "setAnalysisFrozen", id: analysis.id, frozen: false });
  strictEqual(s.nodes[analysis.id].frozen, undefined);
  s = reducer(s, { type: "cacheAnalysisResult", id: analysis.id, result: newer });
  deepStrictEqual(s.nodes[analysis.id].cachedResult, newer);
  // Freezing is an undo step, like any edit.
  s = reducer(s, { type: "setAnalysisFrozen", id: analysis.id, frozen: true });
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes[analysis.id].frozen, undefined);
  // An orphaned sheet can't freeze (it already keeps its last result).
  s = reducer(s, { type: "remove", id: tableId });
  strictEqual(s.nodes[analysis.id].orphaned, true);
  s = reducer(s, { type: "setAnalysisFrozen", id: analysis.id, frozen: true });
  strictEqual(s.nodes[analysis.id].frozen, undefined);
});

check("freezing a data table blocks edits until unfrozen (seq 165)", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  // Known data, so the blocked edit has a value to check against.
  s = reducer(s, { type: "updateTable", id: tableId, data: table.data!, label: "Setup" });
  const edited: TableData = { ...table.data!, rows: [["a", "999", "2.5"], [null, "2", null]] };
  // A table freezes like a results sheet: the flag, and an undo step.
  s = reducer(s, { type: "setTableFrozen", id: tableId, frozen: true });
  strictEqual(s.nodes[tableId].frozen, true);
  // Freezing twice is a no-op, not another undo step.
  const frozenOnce = s;
  s = reducer(s, { type: "setTableFrozen", id: tableId, frozen: true });
  strictEqual(s, frozenOnce);
  // While frozen, an edit is refused outright — same state back, no undo step.
  const before = s;
  s = reducer(s, { type: "updateTable", id: tableId, data: edited, label: "Typing" });
  strictEqual(s, before);
  strictEqual(s.nodes[tableId].data!.rows[0][1], "1");
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes[tableId].frozen, undefined);
  // Unfrozen, the same edit lands.
  s = reducer(s, { type: "setTableFrozen", id: tableId, frozen: true });
  s = reducer(s, { type: "setTableFrozen", id: tableId, frozen: false });
  strictEqual(s.nodes[tableId].frozen, undefined);
  s = reducer(s, { type: "updateTable", id: tableId, data: edited, label: "Typing" });
  strictEqual(s.nodes[tableId].data!.rows[0][1], "999");
  // Duplicating a frozen family leaves the copy editable; the source stays frozen.
  s = reducer(s, { type: "setTableFrozen", id: tableId, frozen: true });
  s = reducer(s, { type: "duplicateFamily", id: tableId });
  const copyId = s.rootOrder[1];
  strictEqual(s.nodes[copyId].frozen, undefined);
  const copyEdited: TableData = { ...table.data!, rows: [["a", "555", "2.5"], [null, "2", null]] };
  s = reducer(s, { type: "updateTable", id: copyId, data: copyEdited, label: "Typing" });
  strictEqual(s.nodes[copyId].data!.rows[0][1], "555");
  strictEqual(s.nodes[tableId].frozen, true);
  strictEqual(s.nodes[tableId].data!.rows[0][1], "999");
  // A non-table can't freeze as a table.
  s = reducer(s, { type: "create", node: { ...analysis, parentId: tableId } });
  s = reducer(s, { type: "setTableFrozen", id: analysis.id, frozen: true });
  strictEqual(s.nodes[analysis.id].frozen, undefined);
});

check("a frozen table survives a save and reload, and a frozen flag on a graph is dropped (seq 165)", () => {
  // The graph's regAnalysisId points at analysis "a1", so the file carries
  // it: without it the link dangles, and the loader repairs a dangling
  // link — that repair, not the frozen flags, would mark the file updated.
  // This check is about the frozen flags, so the file it builds is a sound one.
  const file = {
    nodes: { t1: { ...table, frozen: true }, a1: analysis, g1: { ...graph, frozen: true } },
    rootOrder: ["t1"],
    childOrder: { t1: ["g1", "a1"] },
    activeNodeId: "t1",
  };
  const readBack = read(serializeProjectFile(file));
  strictEqual(readBack.updated, false);
  strictEqual(readBack.project.nodes.t1.frozen, true);
  strictEqual(readBack.project.nodes.g1.frozen, undefined);
  // A non-boolean frozen flag on a table is a hand edit, dropped rather than trusted.
  const sloppy = { ...table, frozen: "yes" as unknown as boolean };
  const readSloppy = read(
    serializeProjectFile({ nodes: { t1: sloppy }, rootOrder: ["t1"], childOrder: { t1: [] }, activeNodeId: "t1" }),
  );
  strictEqual(readSloppy.project.nodes.t1.frozen, undefined);
});

check("MCP freeze-table freezes a table and edit-table/write-table refuse it until unfrozen (seq 165)", async () => {
  const harness = mcpLaggingHarness(true);
  const made = await harness.run("job-165-table", "create-table", {
    table_type: "column",
    columns: ["", "A", "B"],
    rows: [["r1", 1, 2]],
  });
  const tableId = (made.result as { table_id: string }).table_id;
  harness.deps.setTableFrozen = (id, frozen) => harness.dispatch({ type: "setTableFrozen", id, frozen });
  const done = await harness.run("job-165-freeze", "freeze-table", { table_id: tableId, frozen: true });
  deepStrictEqual(done.result, { project_id: "project-1", table_id: tableId, frozen: true });
  strictEqual(harness.state().nodes[tableId]?.frozen, true);
  await rejects(
    harness.run("job-165-edit", "edit-table", { table_id: tableId, op: "insert-rows", at: 0 }),
    /is frozen — unfreeze it/,
  );
  await rejects(
    harness.run("job-165-write", "write-table", {
      table_id: tableId,
      columns: ["", "A", "B"],
      rows: [["r1", 9, 2]],
    }),
    /is frozen — unfreeze it/,
  );
  // Freezing twice is still fine (idempotent); unfreezing restores edits.
  await harness.run("job-165-refreeze", "freeze-table", { table_id: tableId, frozen: true });
  await harness.run("job-165-unfreeze", "freeze-table", { table_id: tableId, frozen: false });
  strictEqual(harness.state().nodes[tableId]?.frozen, undefined);
  const edited = await harness.run("job-165-edit2", "edit-table", { table_id: tableId, op: "insert-rows", at: 0 });
  strictEqual((edited.result as { rows: number }).rows, 2);
  // An unknown id is a plain error.
  await rejects(harness.run("job-165-gone", "freeze-table", { table_id: "nope", frozen: true }), /No table/);
});

