// ── Data-set manager (seq 309) ──────────────────────────────────────────

check("seq 309: reordering data sets moves their columns and values, and the graphs' series follow", () => {
  let t = newGroupedTable(2, 2); // A:Y1 A:Y2 B:Y1 B:Y2
  t = { ...t, rows: [["r1", "1", "2", "3", "4"], ["r2", "5", "6", "7", "8"]] };
  deepStrictEqual(
    dataSetsOf(t, "grouped").map((s) => s.name),
    ["A", "B"],
  );
  const moved = reorderDataSet(t, "grouped", 1, 0);
  deepStrictEqual(moved.columns, ["Title", "B:Y1", "B:Y2", "A:Y1", "A:Y2"]);
  deepStrictEqual(moved.rows, [
    ["r1", "3", "4", "1", "2"],
    ["r2", "7", "8", "5", "6"],
  ]);
  // A graph reads its series from the table, in table order — so the
  // reorder shows there without any graph edit.
  deepStrictEqual(seriesOf(moved, "grouped"), ["B", "A"]);
  // Out of range, or no move: the table comes back unchanged.
  strictEqual(reorderDataSet(t, "grouped", 0, 0), t);
  strictEqual(reorderDataSet(t, "grouped", 2, 0), t);
});

check("seq 309: adding a data set makes a new empty one; removing one drops its columns, and the last set is refused", () => {
  let t = newGroupedTable(2, 2); // A:Y1 A:Y2 B:Y1 B:Y2
  t = { ...t, rows: [["r1", "1", "2", "3", "4"], ["r2", "5", "6", "7", "8"]] };
  const added = addDataSet(t, "grouped");
  deepStrictEqual(
    dataSetsOf(added, "grouped").map((s) => s.name),
    ["A", "B", "C"],
  );
  strictEqual(added.groups, 3);
  deepStrictEqual(added.columns, ["Title", "A:Y1", "A:Y2", "B:Y1", "B:Y2", "C:Y1", "C:Y2"]);
  ok(
    added.rows.every((row) => row[5] === null && row[6] === null),
    "the new set holds no values",
  );
  const removed = removeDataSet(t, "grouped", 1);
  ok(!("error" in removed), "removing B succeeds");
  deepStrictEqual(removed.data.columns, ["Title", "A:Y1", "A:Y2"]);
  deepStrictEqual(removed.data.rows, [
    ["r1", "1", "2"],
    ["r2", "5", "6"],
  ]);
  strictEqual(removed.data.groups, 1);
  const last = removeDataSet(removed.data, "grouped", 0);
  ok("error" in last, "the last set can't go");
  ok(last.error.includes("last data set"), `the refusal explains why: ${"error" in last ? last.error : ""}`);
});

check("seq 309: removing a data set orphans the analyses that ran on it, in one undo step", () => {
  // The cached result must match its test, or the loader drops it on reload.
  const anovaResult: AnalysisResult = { testType: "anova", stats: [{ label: "F", value: 2 }], groups: [], notes: "" };
  const grouped: ProjectNode = {
    id: "t1",
    type: "table",
    name: "Assay",
    parentId: null,
    tableType: "grouped",
    data: {
      ...newGroupedTable(2, 2),
      rows: [
        ["r1", "1", "2", "3", "4"],
        ["r2", "5", "6", "7", "8"],
      ],
    },
  };
  const onB: ProjectNode = {
    id: "a1",
    type: "analysis",
    name: "B only",
    parentId: "t1",
    analysisType: "anova",
    analysisParams: { sets: ["B"] },
    cachedResult: anovaResult,
  };
  const onA: ProjectNode = {
    id: "a2",
    type: "analysis",
    name: "A only",
    parentId: "t1",
    analysisType: "anova",
    analysisParams: { sets: ["A"] },
    cachedResult: anovaResult,
  };
  let s = reducer(makeInitialState(), {
    type: "load",
    nodes: { t1: grouped, a1: onB, a2: onA },
    rootOrder: ["t1"],
    childOrder: { t1: ["a1", "a2"] },
    activeNodeId: "t1",
    filePath: null,
  });
  deepStrictEqual(
    dependentAnalyses(s.nodes, "t1", "B").map((n) => n.id),
    ["a1"],
  );
  const removed = removeDataSet(grouped.data!, "grouped", 1);
  ok(!("error" in removed));
  s = reducer(s, { type: "removeDataSet", id: "t1", data: removed.data, setName: "B", label: "Remove Data Set" });
  deepStrictEqual(s.nodes.t1.data!.columns, ["Title", "A:Y1", "A:Y2"]);
  // The analysis that ran on B is orphaned — frozen results, re-pointable
  // (seq 242) — and moves to the project root, like a deleted table's.
  const orphan = s.nodes.a1;
  strictEqual(orphan.orphaned, true);
  strictEqual(orphan.parentId, null);
  strictEqual(orphan.sourceTableName, "Assay");
  strictEqual(orphan.orphanedDataSet, "B");
  deepStrictEqual(orphan.cachedResult, anovaResult);
  strictEqual(s.rootOrder.includes("a1"), true);
  deepStrictEqual(s.childOrder.t1, ["a2"]);
  // The analysis that ran on A is untouched, still under the table.
  strictEqual(s.nodes.a2.orphaned, undefined);
  strictEqual(s.nodes.a2.parentId, "t1");
  // One undo step takes the table and the orphaning back together.
  strictEqual(s.past.at(-1)?.label, "Remove Data Set");
  s = reducer(s, { type: "undo" });
  deepStrictEqual(s.nodes.t1.data!.columns, ["Title", "A:Y1", "A:Y2", "B:Y1", "B:Y2"]);
  strictEqual(s.nodes.a1.orphaned, undefined);
  strictEqual(s.nodes.a1.parentId, "t1");
  deepStrictEqual(s.childOrder.t1, ["a1", "a2"]);
  // The orphaned set survives a save and reload, so the banner still names it.
  const file = {
    nodes: { t1: grouped, a1: { ...onB, parentId: null, orphaned: true, sourceTableName: "Assay", orphanedDataSet: "B" } },
    rootOrder: ["t1", "a1"],
    childOrder: { t1: [] },
    activeNodeId: "a1",
  };
  const readBack = read(serializeProjectFile(file));
  strictEqual(readBack.updated, false);
  strictEqual(readBack.project.nodes.a1.orphanedDataSet, "B");
});

check("seq 309 MCP: edit-table add-data-set / reorder-data-set / remove-data-set, with the dependent-analysis warning", async () => {
  const harness = mcpLaggingHarness(true);
  const made = await harness.run("job-309-table", "create-table", {
    table_type: "grouped",
    columns: ["", "A:Y1", "A:Y2", "B:Y1", "B:Y2"],
    rows: [
      ["r1", 1, 2, 3, 4],
      ["r2", 5, 6, 7, 8],
    ],
  });
  const tableId = (made.result as { table_id: string }).table_id;
  harness.sync();
  const added = await harness.run("job-309-add", "edit-table", { table_id: tableId, op: "add-data-set" });
  deepStrictEqual((added.result as { data_sets: string[] }).data_sets, ["A", "B", "C"]);
  const moved = await harness.run("job-309-reorder", "edit-table", {
    table_id: tableId,
    op: "reorder-data-set",
    name: "B",
    at: 0,
  });
  deepStrictEqual((moved.result as { data_sets: string[] }).data_sets, ["B", "A", "C"]);
  // The last set can't go: a two-set table refuses its second removal.
  await harness.run("job-309-remove-c", "edit-table", { table_id: tableId, op: "remove-data-set", name: "C" });
  await harness.run("job-309-remove-a", "edit-table", { table_id: tableId, op: "remove-data-set", name: "A" });
  await rejects(
    harness.run("job-309-remove-last", "edit-table", { table_id: tableId, op: "remove-data-set", name: "B" }),
    /last data set/,
  );
  // Add a set back, so the dependent-analysis removal below has a set left after it.
  // (The new set takes the next free letter from its place — "C", not "A".)
  const readded = await harness.run("job-309-readd", "edit-table", { table_id: tableId, op: "add-data-set" });
  deepStrictEqual((readded.result as { data_sets: string[] }).data_sets, ["B", "C"]);
  // A dependent analysis blocks the removal until confirmed, then orphans.
  harness.dispatch({
    type: "create",
    node: {
      id: "a1",
      type: "analysis",
      name: "B only",
      parentId: tableId,
      analysisType: "anova",
      analysisParams: { sets: ["B"] },
      cachedResult: { testType: "anova", stats: [{ label: "F", value: 2 }], groups: [], notes: "" },
    },
  });
  harness.sync();
  await rejects(
    harness.run("job-309-remove-warn", "edit-table", { table_id: tableId, op: "remove-data-set", name: "B" }),
    /data set “B” can't be removed yet/,
  );
  strictEqual(harness.state().nodes[tableId]?.data?.columns.includes("B:Y1"), true);
  const confirmed = await harness.run("job-309-remove-confirm", "edit-table", {
    table_id: tableId,
    op: "remove-data-set",
    name: "B",
    confirm: true,
  });
  deepStrictEqual((confirmed.result as { orphaned_analyses: string[] }).orphaned_analyses, ["B only"]);
  strictEqual(harness.state().nodes.a1?.orphaned, true);
});

// ── Clone a graph ────────────────────────────────────────────────────────

// Deterministic ids for the clone plan: `table-c1`, `analysis-c2`, … in creation order.
const cloneIds = () => {
  let n = 0;
  return () => `c${++n}`;
};
const KEEP_ALL: CloneOptions = { clearY: false, clearX: false, clearTitles: false };

check("cloning a graph duplicates its table, its embedded analysis and its formatting", () => {
  let s = reducer(makeInitialState(), { type: "load", ...payload, filePath: null });
  // A second analysis on the table, not shown on the graph: Prism leaves it behind.
  s = reducer(s, { type: "create", node: { ...analysis, id: "a2", name: "Second fit", parentId: "t1" } });
  const planned = cloneGraphPlan(s, "g1", KEEP_ALL, cloneIds());
  ok("plan" in planned, "the clone should plan");
  const before = s.nodes.g1.graphOptions!;
  s = reducer(s, { type: "cloneGraph", plan: planned.plan });
  strictEqual(s.past.at(-1)?.label, "Clone Graph"); // one undo step takes the whole clone back
  deepStrictEqual(s.rootOrder, ["t1", "c1"]);
  const tableId = "c1";
  strictEqual(s.nodes[tableId].name, "Doses 2");
  strictEqual(s.nodes[tableId].type, "table");
  deepStrictEqual(s.nodes[tableId].data, table.data); // a copy, values and all
  ok(s.nodes[tableId].data !== table.data);
  deepStrictEqual(s.childOrder[tableId], ["c3", "c2"]); // graph then analysis, as in the original
  const graphId = "c3";
  strictEqual(s.activeNodeId, graphId);
  const cloned = s.nodes[graphId];
  strictEqual(cloned.name, "Plot");
  strictEqual(cloned.graphType, "xy-scatter");
  strictEqual(cloned.graphOptions!.title, "My Title");
  strictEqual(cloned.graphOptions!.yMax, 10);
  deepStrictEqual(cloned.graphOptions!.series, { Y1: { color: "#D55E00" } });
  deepStrictEqual(cloned.graphOptions!.points, { "Y1#0": { color: "#0072B2", size: 10 } });
  // The embedded regression comes along, re-pointed at the copy.
  strictEqual(cloned.graphOptions!.regAnalysisId, "c2");
  const clonedAnalysis = s.nodes.c2;
  strictEqual(clonedAnalysis.name, "Fit");
  strictEqual(clonedAnalysis.analysisType, "linear-regression");
  deepStrictEqual(clonedAnalysis.analysisParams, { y: "Y1", forceOrigin: true });
  // The analysis not on the graph stays behind, and the original is untouched.
  strictEqual(Object.keys(s.nodes).length, 7);
  ok(!Object.values(s.nodes).some((n) => n.name === "Second fit" && n.parentId === tableId));
  strictEqual(s.nodes.g1.graphOptions!.regAnalysisId, "a1");
  deepStrictEqual(s.nodes.g1.graphOptions, before);
  // Undo takes the whole clone back; redo brings it back.
  s = reducer(s, { type: "undo" });
  strictEqual(Object.keys(s.nodes).length, 4);
  deepStrictEqual(s.rootOrder, ["t1"]);
  s = reducer(s, { type: "redo" });
  strictEqual(Object.keys(s.nodes).length, 7);
});

check("cloning a graph clears Y values by default and keeps X values and titles", () => {
  const s = reducer(makeInitialState(), { type: "load", ...payload, filePath: null });
  const planned = cloneGraphPlan(s, "g1", DEFAULT_CLONE_OPTIONS, cloneIds());
  ok("plan" in planned);
  deepStrictEqual(planned.plan.nodes.c1.data, {
    columns: ["Title", "X", "Y1"],
    rows: [
      ["a", "1", null],
      [null, "2", null],
    ],
  });
  ok(!("excluded" in planned.plan.nodes.c1.data!)); // exclusions pointed at cleared cells
  // The embedded analysis still comes along: clearing data doesn't drop it.
  ok(planned.plan.nodes.c2 && planned.plan.nodes.c2.type === "analysis");
  strictEqual(DEFAULT_CLONE_OPTIONS.clearY, true);
  strictEqual(DEFAULT_CLONE_OPTIONS.clearX, false);
  strictEqual(DEFAULT_CLONE_OPTIONS.clearTitles, false);
});

check("cloning a graph can clear X values and titles too", () => {
  const s = reducer(makeInitialState(), { type: "load", ...payload, filePath: null });
  const planned = cloneGraphPlan(s, "g1", { clearY: true, clearX: true, clearTitles: true }, cloneIds());
  ok("plan" in planned);
  deepStrictEqual(planned.plan.nodes.c1.data!.rows, [
    [null, null, null],
    [null, null, null],
  ]);
});

check("cloning a column table's graph clears every data cell (there is no X to keep)", () => {
  let s = makeInitialState();
  const tableId = s.rootOrder[0];
  s = reducer(s, {
    type: "updateTable",
    id: tableId,
    data: { columns: ["Title", "A", "B"], rows: [["r1", "1", "2"]] },
    label: "Typing",
  });
  s = reducer(s, {
    type: "create",
    node: { ...graph, id: "g9", parentId: tableId, graphType: "individual", graphOptions: newGraphOptions("individual") },
  });
  const planned = cloneGraphPlan(s, "g9", DEFAULT_CLONE_OPTIONS, cloneIds());
  ok("plan" in planned);
  deepStrictEqual(planned.plan.nodes.c1.data!.rows, [["r1", null, null]]);
});

check("cloning refuses a missing graph and a node that isn't a graph", () => {
  const s = reducer(makeInitialState(), { type: "load", ...payload, filePath: null });
  const missing = cloneGraphPlan(s, "nope", KEEP_ALL, cloneIds());
  ok("error" in missing);
  const notGraph = cloneGraphPlan(s, "a1", KEEP_ALL, cloneIds());
  ok("error" in notGraph);
});

check("a cloned graph keeps a link to an analysis outside its family", () => {
  const other: ProjectNode = { ...table, id: "t2", name: "Other" };
  const far: ProjectNode = { ...analysis, id: "a9", name: "Far fit", parentId: "t2" };
  const linked: ProjectNode = {
    ...graph,
    graphOptions: { ...graph.graphOptions!, regAnalysisId: "a9" },
  };
  const s = reducer(makeInitialState(), {
    type: "load",
    nodes: { t1: table, t2: other, a9: far, g1: linked },
    rootOrder: ["t1", "t2"],
    childOrder: { t1: ["g1"], t2: ["a9"] },
    activeNodeId: "g1",
    filePath: null,
  });
  const planned = cloneGraphPlan(s, "g1", KEEP_ALL, cloneIds());
  ok("plan" in planned);
  strictEqual(Object.keys(planned.plan.nodes).length, 2); // the table and the graph only
  strictEqual(planned.plan.nodes.c2.graphOptions!.regAnalysisId, "a9");
  strictEqual(Object.values(planned.plan.nodes).filter((n) => n.name === "Far fit").length, 0);
});

check("quick edits to one graph undo together; a pause starts a new step", () => {
  const start = makeInitialState();
  let s = reducer(start, { type: "create", node: { ...graph, parentId: start.rootOrder[0] } });
  const set = (title: string, at: number) =>
    (s = reducer(s, { type: "updateGraph", id: graph.id, options: { ...DEFAULT_GRAPH_OPTIONS, title }, at }));
  set("T", 1000);
  set("Ti", 1200);
  set("Title", 1400);
  set("Title 2", 5000);
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes[graph.id].graphOptions!.title, "Title");
  s = reducer(s, { type: "undo" });
  strictEqual(s.nodes[graph.id].graphOptions, graph.graphOptions);
});

check("changes that change nothing, and opening a file, leave no Undo step", () => {
  let s = makeInitialState();
  s = reducer(s, { type: "reorderRoot", order: [...s.rootOrder] });
  strictEqual(s.past.length, 0);
  s = reducer(s, { type: "rename", id: s.rootOrder[0], name: "Table 1" });
  strictEqual(s.past.length, 0);
  s = reducer(s, { type: "rename", id: s.rootOrder[0], name: "Other" });
  s = reducer(s, { type: "load", nodes: {}, rootOrder: [], childOrder: {}, activeNodeId: null, filePath: "/x.hlx" });
  strictEqual(s.past.length, 0);
});

