check("Open Recent loads FileHandle entries, migrating legacy plain paths", () => {
  const stored: Record<string, string> = {};
  const storage = {
    getItem: (k: string) => stored[k] ?? null,
    setItem: (k: string, v: string) => void (stored[k] = v),
  };
  Object.assign(globalThis, { localStorage: storage });
  try {
    for (const bad of ['{"a":1}', "[1, null]", "not json"]) {
      stored["titer.recent"] = bad;
      deepStrictEqual(loadRecents(), []);
    }
    // Legacy plain-path strings migrate to local entries.
    stored["titer.recent"] = '["/a.hlx", 3, "/b.hlx"]';
    deepStrictEqual(loadRecents(), [
      { kind: "local", path: "/a.hlx" },
      { kind: "local", path: "/b.hlx" },
    ]);
    // New-format entries (local + remote) load as-is.
    stored["titer.recent"] = JSON.stringify([
      { kind: "local", path: "/a.hlx" },
      { kind: "remote", provider: "box", accountId: "u1", fileId: "123", path: "/Research/Data.hlx" },
    ]);
    deepStrictEqual(loadRecents(), [
      { kind: "local", path: "/a.hlx" },
      { kind: "remote", provider: "box", accountId: "u1", fileId: "123", path: "/Research/Data.hlx" },
    ]);
    // Malformed remote entries (missing fileId) are dropped, well-formed kept.
    stored["titer.recent"] =
      '[{"kind":"remote","provider":"box","accountId":"u1","fileId":"f9","path":"/Budget.hlx"},{"kind":"remote","provider":"box","accountId":"u1","path":"/NoId.hlx"}]';
    deepStrictEqual(loadRecents(), [
      { kind: "remote", provider: "box", accountId: "u1", fileId: "f9", path: "/Budget.hlx" },
    ]);
  } finally {
    delete (globalThis as { localStorage?: unknown }).localStorage;
  }
});

check("Recently-used analyses: recency order, cap at 5, persistence, clear, and the not-applicable check (seq 298)", () => {
  const stored: Record<string, string> = {};
  const storage = {
    getItem: (k: string) => stored[k] ?? null,
    setItem: (k: string, v: string) => void (stored[k] = v),
  };
  Object.assign(globalThis, { localStorage: storage });
  try {
    // Empty state: nothing recorded yet, so the picker shows no section.
    deepStrictEqual(loadRecentAnalyses(), []);
    // Three different runs land most-recent-first, with display name + timestamp.
    recordRecentAnalysis("descriptive-statistics", 1000);
    recordRecentAnalysis("correlation", 2000);
    recordRecentAnalysis("two-way-anova", 3000);
    deepStrictEqual(loadRecentAnalyses(), [
      { type: "two-way-anova", label: "Two-Way ANOVA", at: 3000 },
      { type: "correlation", label: "Correlation", at: 2000 },
      { type: "descriptive-statistics", label: "Descriptive Statistics", at: 1000 },
    ]);
    // Re-running one moves it to the front instead of duplicating it.
    recordRecentAnalysis("descriptive-statistics", 4000);
    deepStrictEqual(
      loadRecentAnalyses().map((e) => e.type),
      ["descriptive-statistics", "two-way-anova", "correlation"],
    );
    // The list caps at 5: the oldest drops off.
    recordRecentAnalysis("shapiro-wilk", 5000);
    recordRecentAnalysis("one-sample-t", 6000);
    recordRecentAnalysis("outliers", 7000);
    deepStrictEqual(
      loadRecentAnalyses().map((e) => e.type),
      ["outliers", "one-sample-t", "shapiro-wilk", "descriptive-statistics", "two-way-anova"],
    );
    strictEqual(MAX_RECENT_ANALYSES, 5);
    // Persists across relaunch: the stored list reads back the same.
    strictEqual(JSON.parse(stored["titer.recent-analyses"]).length, 5);
    strictEqual(loadRecentAnalyses()[0]?.type, "outliers");
    // Malformed stored entries are dropped, well-formed kept.
    stored["titer.recent-analyses"] = JSON.stringify([
      { type: "correlation", label: "Correlation", at: 2000 },
      { type: "no-such-test", label: "Nope", at: 1 },
      { type: "outliers", label: 7, at: "soon" },
      null,
    ]);
    deepStrictEqual(loadRecentAnalyses(), [{ type: "correlation", label: "Correlation", at: 2000 }]);
    // Clear empties the list.
    recordRecentAnalysis("correlation", 9000);
    clearRecentAnalyses();
    deepStrictEqual(loadRecentAnalyses(), []);
    // The not-applicable check: a Grouped-only test is not offered on a Column table.
    ok(isAnalysisOffered("two-way-anova", "grouped"));
    ok(!isAnalysisOffered("two-way-anova", "column"));
    ok(isAnalysisOffered("descriptive-statistics", "column"));
    ok(isAnalysisOffered("compare-many-groups", "column"));
  } finally {
    delete (globalThis as { localStorage?: unknown }).localStorage;
  }
});

check("My Palettes keep, replace and delete palettes; a gradient of few colors blends evenly", async () => {
  const stored: Record<string, string> = {};
  const storage = {
    getItem: (k: string) => stored[k] ?? null,
    setItem: (k: string, v: string) => void (stored[k] = v),
  };
  const lab = { name: "Lab", kind: "categorical" as const, colors: ["#111111", "#222222"] };
  const heat = { name: "Heat", kind: "sequential" as const, colors: ["#FFFFFF", "#FF0000"] };
  Object.assign(globalThis, { localStorage: storage });
  try {
    ok((await keepPalette({ ...lab, reversed: true })) && (await keepPalette(heat)));
    deepStrictEqual(await loadMyPalettes(), [lab, heat]); // kept as shown: no `reversed`
    ok(await keepPalette({ ...lab, name: "Lab 2" }, "Lab"));
    deepStrictEqual(
      (await loadMyPalettes()).map((p) => p.name),
      ["Lab 2", "Heat"],
    );
    ok(await deletePalette("Lab 2"));
    deepStrictEqual(await loadMyPalettes(), [heat]);
    // A broken entry is left out, the others kept.
    stored["titer.palettes"] = JSON.stringify([heat, { name: "No colors", colors: [] }, 7]);
    deepStrictEqual(await loadMyPalettes(), [heat]);
  } finally {
    delete (globalThis as { localStorage?: unknown }).localStorage;
  }
  deepStrictEqual(
    [0, 1, 2, 3, 4].map((i) => paletteColor(heat, i, 5)),
    ["#FFFFFF", "#FFBFBF", "#FF8080", "#FF4040", "#FF0000"],
  );
  ok(isTiterPalette("viridis") && isTiterPalette("Okabe-Ito") && !isTiterPalette("Lab"));
  // A gradient of one color, from a broken file, runs from it to itself.
  deepStrictEqual(readPalette({ name: "Red", kind: "sequential", colors: ["#FF0000"] })!.colors, [
    "#FF0000",
    "#FF0000",
  ]);
});

check("a narrow window narrows the sidebar for the inspector only where there is one", () => {
  const layout = { sidebar: true, sidebarWidth: 224, inspector: true, inspectorWidth: 256, gallery: false };
  deepStrictEqual(fitWidths(layout, 700, true), { sidebarWidth: 180, inspectorWidth: 220 });
  strictEqual(fitWidths(layout, 700, false).sidebarWidth, 224);
});

check("a graph too wide for its pane is fitted to the pane, never enlarged", () => {
  // A 640×460 sheet in a 520×600 pane (inspector open at a 1000px window):
  // 520 / (640 + 96) ≈ 0.71.
  const fitted = fitZoom(520, 600, 640, 460);
  ok(fitted > 0.7 && fitted < 0.72);
  // Room to spare: no scaling.
  strictEqual(fitZoom(1000, 800, 640, 460), 1);
  // Height-bound: a short pane clamps on height, not width (400 / (460 + 96) ≈ 0.72).
  const short = fitZoom(1000, 400, 640, 460);
  ok(short > 0.71 && short < 0.73);
  // A small graph is never enlarged.
  strictEqual(fitZoom(1000, 800, 200, 100), 1);
  // Fitting is view-only: it takes the saved size, it does not change it.
  const saved = { ...DEFAULT_GRAPH_OPTIONS };
  fitZoom(520, 600, saved.width, saved.height);
  deepStrictEqual(saved, DEFAULT_GRAPH_OPTIONS);
});


