check(".pzfx import keeps date X values in their own column when row titles exist", () => {
  const { imported, table } = importedTable("x_date_row_titles");
  strictEqual(table.name, "Sample Data");
  strictEqual(table.tableType, "xy");
  deepStrictEqual(table.data!.columns, ["Title", "Date X", "Date X (date)", "Observation"]);
  strictEqual(table.data!.rows.length, 5);
  deepStrictEqual(table.data!.rows[0], ["Sample A", "0", "16-Jan-2004", "120"]);
  deepStrictEqual(table.data!.rows[1], ["Sample B", "5.22929500342231", "9-Apr-2009", "64"]);
  deepStrictEqual(table.data!.rows[4], ["Sample E", "8.27652292950034", "26-Apr-2012", "52"]);
  // The warning must be true in this branch: the row titles are the original
  // ones, the dates live in their own column — neither "kept as row titles"
  // (false: the titles are the samples') nor "dropped" (false: kept).
  ok(
    imported.issues.some((i) => i.message.includes("kept in a “Date X (date)” column")),
    "says the dates were kept in their own column",
  );
  ok(
    !imported.issues.some((i) => i.message.includes("kept as row titles") || i.message.includes("were dropped")),
    "never claims the dates were kept as row titles or dropped",
  );
});

check(".pzfx import reads a Survival table (time + event codes)", () => {
  const { imported, table } = importedTable("survival");
  strictEqual(table.tableType, "survival");
  deepStrictEqual(table.data!.columns, ["Title", "Days", "Control", "Treatment A", "Treatment B"]);
  strictEqual(table.data!.rows.length, 27);
  deepStrictEqual(table.data!.rows[0], ["CO", "78", "1", null, null]);
  deepStrictEqual(table.data!.rows[26], ["OO", "351", null, null, "1"]);
  ok(imported.issues.some((i) => i.message.includes("Survival table")), "says the survival analysis applies");
});

check("the survival analysis reproduces the log-rank value on survival.pzfx", async () => {
  const { table } = importedTable("survival");
  const out = await runAnalysis("survival", table.data!, { curveTest: "logrank", correction: "holm" });
  if ("error" in out) throw new Error(out.error);
  const stat = (label: string) => out.stats.find((s) => s.label === label)?.value;
  close(stat("Chi-square"), 4.844, 1e-3, "chi-square");
  strictEqual(stat("df"), 2);
  close(stat("P value"), 0.0888, 1e-3, "P value");
});

check("a survival curve draws its Number at Risk table on survival.pzfx", () => {
  // "Three groups": Control N=10, Treatment A N=10, Treatment B N=7, last
  // time 378 — the table's columns are the X-axis major ticks (0, 100, 200,
  // 300), set explicitly so the counts align with them.
  const { table } = importedTable("survival");
  const options = newGraphOptions("survival");
  const fig = GRAPHS.survival.build(readTable(table.data!).columns, options, paintOf(options, 3));
  deepStrictEqual((fig.layout.xaxis as { tickvals?: number[] }).tickvals, [0, 100, 200, 300]);
  const annotations = (fig.layout.annotations as { xref?: string; x?: number; text?: string; showarrow?: boolean }[] | undefined) ?? [];
  // Every count sits on a tick's X; no table text is draggable (no arrows).
  ok(
    annotations
      .filter((a) => a.xref === "x")
      .every((a, i) => a.x === [0, 100, 200, 300][i % 4]),
    "counts sit on the tick X positions",
  );
  ok(annotations.every((a) => a.showarrow === false), "no table text is draggable");
  // At-risk counts are subjects with time ≥ tick; cumulative censored are
  // subjects censored before the tick.
  deepStrictEqual(tableRows(fig), [
    { label: "Control", values: ["10", "7", "5", "3"] },
    { label: "Control censored", values: ["0", "0", "1", "1"] },
    { label: "Treatment A", values: ["10", "9", "5", "1"] },
    { label: "Treatment A censored", values: ["0", "0", "2", "2"] },
    { label: "Treatment B", values: ["7", "7", "7", "4"] },
    { label: "Treatment B censored", values: ["0", "0", "0", "1"] },
  ]);
});

check("a survival curve's Number at Risk table sits below the X axis, not in the plot", () => {
  // Plotly's "paper" coordinates are fractions of the PLOT area, not the
  // figure: y = 0 is the X-axis line and x = 0 its left end — so a table
  // below the axis needs negative paper-y, and labels left of the axis
  // negative paper-x. The old code divided px-from-figure-bottom by the
  // figure height, which Plotly read as a fraction of the plot: the table
  // landed inside the plot, over the curves and the "20" tick label, with
  // the tick-0 column colliding with the row labels (Mac GUI proof, nar1).
  // The placement is pinned here in figure JSON: every table annotation
  // below the axis line, inside the grown bottom margin, rows in order,
  // labels left of the axis inside the widened left margin.
  const assertPlaced = (fig: GraphFigure, options: GraphOptions) => {
    const margin = fig.layout.margin as { l: number; r: number; t: number; b: number };
    const plotW = options.width - margin.l - margin.r;
    const plotH = options.height - margin.t - margin.b;
    ok(plotW > 0 && plotH > 0, "plot area exists");
    const annotations = (fig.layout.annotations as { xref?: string; yref?: string; x?: number; y?: number; text?: string }[] | undefined) ?? [];
    const labels = annotations.filter((a) => a.xref === "paper");
    const counts = annotations.filter((a) => a.xref === "x");
    ok(labels.length > 1 && counts.length > 0, "table has a title, rows and counts");
    // Rows below the axis line, inside the grown bottom margin.
    for (const a of [...labels, ...counts]) {
      ok(a.y! < 0, `table text ${JSON.stringify(a.text)} sits below the axis (y=${a.y})`);
      ok(a.y! > -margin.b / plotH, `table text ${JSON.stringify(a.text)} stays inside the bottom margin (y=${a.y})`);
    }
    // Rows descend in order: title closest to the axis, then each group.
    for (let i = 1; i < labels.length; i++)
      ok(labels[i]!.y! < labels[i - 1]!.y!, `row ${i} sits below row ${i - 1}`);
    // The title row clears the tick labels and the axis title (both sit
    // between the axis line and the table).
    ok(
      -labels[0]!.y! * plotH > options.fontSize + options.xTitleGap + options.fontSize + 8,
      `title row clears the tick labels and axis title (y=${labels[0]!.y})`,
    );
    // Labels left of the axis line, inside the widened left margin.
    for (const a of labels) {
      ok(a.x! < 0, `label ${JSON.stringify(a.text)} sits left of the axis (x=${a.x})`);
      ok(a.x! > -margin.l / plotW, `label ${JSON.stringify(a.text)} stays inside the left margin (x=${a.x})`);
    }
    // Each count sits on its own row.
    const ticks = (fig.layout.xaxis as { tickvals?: number[] }).tickvals ?? [];
    labels.slice(1).forEach((label, k) => {
      const row = counts.slice(k * ticks.length, (k + 1) * ticks.length);
      strictEqual(row.length, ticks.length, `row ${label.text} has a count per tick`);
      ok(row.every((c) => c.y === label.y), `row ${label.text} counts sit on the row`);
    });
  };
  const { table } = importedTable("survival");
  const options = newGraphOptions("survival");
  assertPlaced(GRAPHS.survival.build(readTable(table.data!).columns, options, paintOf(options, 3)), options);
  // Counts mode: same placement, fewer rows (no censored rows).
  const countsOptions: GraphOptions = { ...newGraphOptions("survival"), survivalMode: "counts" };
  const countsData = {
    columns: ["Title", "X", "A", "B"],
    rows: [
      [null, "0", "10", "4"],
      [null, "10", "8", "4"],
      [null, "20", "5", "2"],
      [null, "30", "5", "0"],
    ],
  };
  assertPlaced(GRAPHS.survival.build(readTable(countsData).columns, countsOptions, paintOf(countsOptions, 2)), countsOptions);
});

