check(".pzfx import reads '1,000' as 1000 in a dot-decimal file — and keeps a comma decimal a decimal (FF-F8)", () => {
  // The fixture is a dot-decimal file ("1.5", "2.5" prove the decimal
  // separator is "."), so "1,000" can only be a thousands separator: reading
  // it as 1.000 would be a 1000x error. The guard leg is a comma-decimal
  // file ("7,5" proves the separator is ","): there "1,875" is 1.875, as in
  // the real SaturationBinding.pzfx — the two readings are told apart by the
  // file, never by the string alone.
  const { table } = importedTable("column_thousands");
  deepStrictEqual(table.data!.columns, ["Title", "Aa"]);
  deepStrictEqual(table.data!.rows, [
    [null, "1.5"],
    [null, "1000"],
    [null, "2.5"],
  ]);
  const commaDecimal = parsePzfx(
    `<?xml version="1.0" encoding="UTF-8"?><GraphPadPrismFile PrismXMLVersion="5.00">` +
      `<Table ID="Table0" XFormat="none" TableType="OneWay" EVFormat="AsteriskAfterNumber">` +
      `<Title>Data 1</Title>` +
      `<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>Aa</Title><Subcolumn>` +
      `<d>1,875</d><d>7,5</d>` +
      `</Subcolumn></YColumn></Table></GraphPadPrismFile>`,
  );
  strictEqual(commaDecimal.tables.length, 1, "comma-decimal table imports");
  const commaNode = commaDecimal.project.nodes[commaDecimal.project.rootOrder[0]];
  if (!commaNode || commaNode.type !== "table") throw new Error("comma-decimal: no table node");
  deepStrictEqual(commaNode.data!.rows, [
    [null, "1.875"],
    [null, "7.5"],
  ]);
});

check(".pzfx import normalizes comma-decimal scientific notation (Issue 56)", () => {
  // "4,096e+007" and "1,5e-3" used to stay un-normalized and parse as null:
  // normalizeNumber's comma-decimal regex had no exponent group, so the
  // comma survived and parseCell dropped the value. Plain "1,5" is the
  // control — it already worked and must keep working.
  const imported = parsePzfx(
    `<?xml version="1.0" encoding="UTF-8"?><GraphPadPrismFile PrismXMLVersion="5.00">` +
      `<Table ID="Table0" XFormat="none" TableType="OneWay" EVFormat="AsteriskAfterNumber">` +
      `<Title>Data 1</Title>` +
      `<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>Aa</Title><Subcolumn>` +
      `<d>4,096e+007</d><d>1,5e-3</d><d>1,5</d>` +
      `</Subcolumn></YColumn></Table></GraphPadPrismFile>`,
  );
  strictEqual(imported.tables.length, 1, "comma-decimal-exponent table imports");
  const node = imported.project.nodes[imported.project.rootOrder[0]];
  if (!node || node.type !== "table") throw new Error("comma-decimal-exponent: no table node");
  deepStrictEqual(node.data!.rows, [
    [null, "4.096e+007"],
    [null, "1.5e-3"],
    [null, "1.5"],
  ]);
  strictEqual(parseCell("4.096e+007"), 40960000);
  strictEqual(parseCell("1.5e-3"), 0.0015);
  // The same exponent form converts through the table's right-click path.
  deepStrictEqual(
    convertCommaDecimals({
      columns: ["Title", "Aa"],
      rows: [
        [null, "1,5e-3"],
        [null, "4,096e+007"],
        [null, "1,5"],
      ],
    }).rows,
    [
      [null, "1.5e-3"],
      [null, "4.096e+007"],
      [null, "1.5"],
    ],
  );
});

check(".pzfx import preserves duplicate column names exactly (BUG-4)", () => {
  // Two Y columns both titled "Control", plus a third already titled
  // "Control 2" and a third "Control" — the reader keeps every title
  // verbatim, exactly as the .prism import does and as the file holds
  // them. Renaming the second duplicate ("Control" → "Control 2") used
  // to change analysis labels and re-run hashes after a .pzfx
  // round-trip (BUG-4: `MitoFactory` → `MitoFactory 2`), even though
  // all values were identical. Each column still keeps its own values,
  // positionally — the values never depended on the rename.
  const text = `<?xml version="1.0" encoding="UTF-8"?><GraphPadPrismFile PrismXMLVersion="5.00">
<Table ID="Table0" XFormat="none" TableType="OneWay">
<Title>Data 1</Title>
<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>Control</Title><Subcolumn><d>1.</d><d>2.</d></Subcolumn></YColumn>
<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>Control</Title><Subcolumn><d>10.</d><d>20.</d></Subcolumn></YColumn>
<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>Control 2</Title><Subcolumn><d>100.</d><d>200.</d></Subcolumn></YColumn>
<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>Control</Title><Subcolumn><d>1000.</d><d>2000.</d></Subcolumn></YColumn>
</Table>
</GraphPadPrismFile>`;
  const imported = parsePzfx(text);
  strictEqual(imported.tables.length, 1);
  const node = imported.project.nodes[imported.project.rootOrder[0]];
  if (!node || node.type !== "table") throw new Error("no table node");
  deepStrictEqual(node.data!.columns, ["Title", "Control", "Control", "Control 2", "Control"]);
  // Every column keeps its own data, by position: the second "Control"
  // holds 10./20., the third "Control" holds 1000./2000.
  deepStrictEqual(node.data!.rows, [
    [null, "1.", "10.", "100.", "1000."],
    [null, "2.", "20.", "200.", "2000."],
  ]);
  strictEqual(node.data!.rows[0][2], "10.");
  strictEqual(node.data!.rows[0][4], "1000.");
  ok(!imported.issues.some((i) => i.message.includes("duplicate column names were renamed")), "no rename warning");
});

check(".pzfx import preserves trailing spaces in table, column and row titles (BUG-4/BUG-7)", () => {
  // A table titled `XY␣`, Y columns `0nM␣` (twice), and a row titled
  // `Control␣`: the reader used to trim all three, so the table went
  // missing under its real name, the columns were deduped to
  // `0nM`/`0nM 2`, and the row title changed value. The file holds the
  // spaces verbatim; the import must too.
  const text = `<?xml version="1.0" encoding="UTF-8"?><GraphPadPrismFile PrismXMLVersion="5.00">
<Table ID="Table0" XFormat="none" TableType="OneWay">
<Title>XY </Title>
<RowTitlesColumn Width="89"><Subcolumn><d>Control </d><d>Sorbitol</d></Subcolumn></RowTitlesColumn>
<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>0nM </Title><Subcolumn><d>1.</d><d>2.</d></Subcolumn></YColumn>
<YColumn Width="89" Decimals="0" Subcolumns="1"><Title>0nM </Title><Subcolumn><d>10.</d><d>20.</d></Subcolumn></YColumn>
</Table>
</GraphPadPrismFile>`;
  const imported = parsePzfx(text);
  deepStrictEqual(imported.tables, ["XY "]);
  const node = imported.project.nodes[imported.project.rootOrder[0]];
  if (!node || node.type !== "table") throw new Error("no table node");
  strictEqual(node.name, "XY ");
  deepStrictEqual(node.data!.columns, ["Title", "0nM ", "0nM "]);
  deepStrictEqual(node.data!.rows, [
    ["Control ", "1.", "10."],
    ["Sorbitol", "2.", "20."],
  ]);
});

check(".pzfx import collapses multi-line column titles like the .prism reader, so a .prism round-trip is identical (battery FAIL#1)", async () => {
  // Real battery file zenodo-15082902-cpz-qpcr…: every table's sixth Y
  // column is titled "+Barb\r\n+Oxy". The .pzfx import kept the raw line
  // break, but the .prism reader collapses it to "+Barb +Oxy" (cleanText),
  // so the export→reimport comparison saw DIFFERS on all 16 tables even
  // though every value was identical. The importer now applies the same
  // single-line rule, and the full .prism cycle is identical.
  const text = `<?xml version="1.0" encoding="UTF-8"?><GraphPadPrismFile PrismXMLVersion="5.00">
<Table ID="Table0" XFormat="none" TableType="OneWay">
<Title>Data 1</Title>
<YColumn Width="89" Decimals="9" Subcolumns="1"><Title>Ctrl</Title><Subcolumn><d>0,0000875644</d><d>0,000110714</d></Subcolumn></YColumn>
<YColumn Width="89" Decimals="9" Subcolumns="1"><Title>+Barb\r\n+Oxy</Title><Subcolumn><d>0,000180773</d><d>0,0001674</d></Subcolumn></YColumn>
</Table>
</GraphPadPrismFile>`;
  const imported = parsePzfx(text);
  const node = imported.project.nodes[imported.project.rootOrder[0]];
  if (!node || node.type !== "table") throw new Error("no table node");
  deepStrictEqual(node.data!.columns, ["Title", "Ctrl", "+Barb +Oxy"]);
  const written = await writePrism(imported.project, "1.7.0");
  const back = await convertPrism(written.bytes, "round-trip.prism");
  const backNode = Object.values(back.project.nodes).find((n) => n.type === "table");
  if (!backNode || backNode.type !== "table") throw new Error("no table node after round-trip");
  deepStrictEqual(backNode.data!.columns, node.data!.columns);
  deepStrictEqual(backNode.data!.rows, node.data!.rows);
});

