check("the survival analysis refuses bad survival data", async () => {
  const cases: [TableData, string][] = [
    // A code that isn't 0 or 1.
    [logRankTable(["Title", "Days", "A", "B"], [["", "3", "2", "1"]]), "enter 1 for an event, 0 for a censored subject"],
    // Only one group with data.
    [logRankTable(["Title", "Days", "A", "B"], [["", "3", "1", ""]]), "at least 2 groups holding subjects"],
  ];
  for (const [data, message] of cases) {
    const out = await runAnalysis("survival", data, { curveTest: "logrank", correction: "holm" });
    if (!("error" in out) || !out.error.includes(message)) {
      throw new Error(`expected an error mentioning "${message}", got ${JSON.stringify(out)}`);
    }
  }
});

// Seq 193: the file reader's merged `correction` list admits every family's
// values, so a multiple-t-tests correction on a survival analysis must be
// refused, not sent to `p.adjust` as a method it does not know.
check("the survival analysis refuses a multiple-t-tests correction", async () => {
  const out = await runAnalysis(
    "survival",
    logRankTable(
      ["Title", "Days", "A", "B", "C"],
      [
        ["", "3", "1", "1", "1"],
        ["", "5", "0", "1", "0"],
      ],
    ),
    { curveTest: "logrank", correction: "holm-sidak" } as never,
  );
  ok("error" in out && /Unknown survival correction/.test(out.error), "holm-sidak on survival errors cleanly");
});

// v1.5.0 m17: the log-rank (and Cox on a Survival table) accepted a time of
// 0 while Cox regression rejected time ≤ 0. Survival times must be positive.
check("the survival analysis refuses a time of 0, like Cox does", async () => {
  const data = logRankTable(
    ["Title", "Days", "Treated", "Placebo"],
    [
      ["", "0", "1", ""],
      ["", "5", "", "1"],
      ["", "7", "0", "1"],
      ["", "8", "", "1"],
      ["", "10", "1", ""],
      ["", "12", "", "0"],
      ["", "15", "1", "1"],
      ["", "20", "0", ""],
    ],
  );
  for (const curveTest of ["logrank", "gehan"] as const) {
    const out = await runAnalysis("survival", data, { curveTest, correction: "holm" });
    if (!("error" in out) || !out.error.includes("must be positive")) {
      throw new Error(`survival/${curveTest}: expected a "must be positive" error, got ${JSON.stringify(out).slice(0, 200)}`);
    }
  }
  const cox = await runAnalysis("cox", data, {});
  if (!("error" in cox) || !cox.error.includes("must be positive")) {
    throw new Error(`cox: expected a "must be positive" error, got ${JSON.stringify(cox).slice(0, 200)}`);
  }
  // A negative time errors with the same message (it used to say only
  // "Times can't be negative.").
  const negative = logRankTable(
    ["Title", "Days", "Treated", "Placebo"],
    [
      ["", "-1", "1", ""],
      ["", "5", "", "1"],
      ["", "7", "0", "1"],
      ["", "8", "", "1"],
    ],
  );
  const neg = await runAnalysis("survival", negative, { curveTest: "logrank", correction: "holm" });
  if (!("error" in neg) || !neg.error.includes("must be positive")) {
    throw new Error(`expected a "must be positive" error for a negative time, got ${JSON.stringify(neg).slice(0, 200)}`);
  }
});

// Seq 158: a survival analysis from a Multiple Variables table assigns its variables —
// time, event codes, grouping — and compares the same curves as the same subjects in
// a Survival table (the log-rank fixture above, one subject per row).
check("a survival analysis on a Multiple Variables table assigns its variables", async () => {
  const data: TableData = {
    columns: ["Title", "Time", "Status", "Group"],
    rows: [
      [null, "3", "1", "Treated"],
      [null, "5", "1", "Placebo"],
      [null, "7", "0", "Treated"],
      [null, "7", "1", "Placebo"],
      [null, "8", "1", "Placebo"],
      [null, "10", "1", "Treated"],
      [null, "12", "0", "Placebo"],
      [null, "15", "1", "Treated"],
      [null, "15", "1", "Placebo"],
      [null, "20", "0", "Treated"],
    ],
  };
  const wizard = WIZARDS["survival"]!;
  const ids = (a: Answers, table: TableData = data) =>
    wizard.questions(a, readTable(table), "multiple").flatMap((q) => (q ? [q.id] : []));
  deepStrictEqual(ids({}), ["time", "status", "groupBy", "curveTest"]);
  deepStrictEqual(ids({ time: "Time", status: "Status", groupBy: "Group" }), ["time", "status", "groupBy", "curveTest"]);
  deepStrictEqual(
    wizard.finish({ time: "Time", status: "Status", groupBy: "Group", curveTest: "logrank" }, readTable(data), "multiple")
      .params,
    { curveTest: "logrank", correction: "holm", time: "Time", status: "Status", groupBy: "Group" },
  );
  // Three groups: the trend test and the correction question appear.
  const three: TableData = {
    columns: ["Title", "Time", "Status", "Group"],
    rows: [
      [null, "4", "1", "A"],
      [null, "6", "1", "B"],
      [null, "9", "1", "C"],
    ],
  };
  deepStrictEqual(ids({ time: "Time", status: "Status", groupBy: "Group" }, three), [
    "time",
    "status",
    "groupBy",
    "curveTest",
    "correction",
  ]);
  const curveTest = wizard
    .questions({ time: "Time", status: "Status", groupBy: "Group" }, readTable(three), "multiple")
    .find((q) => q && q.id === "curveTest");
  ok(curveTest && curveTest.kind === "choice" && curveTest.options.some((o) => o.value === "trend"));
  const out = await runAnalysis("survival", data, {
    curveTest: "logrank",
    correction: "holm",
    time: "Time",
    status: "Status",
    groupBy: "Group",
  });
  if ("error" in out) throw new Error(`MV survival analysis failed: ${out.error}`);
  const stat = (label: string) => out.stats.find((s) => s.label === label)?.value;
  close(stat("Chi-square"), 0.528, 1e-3, "chi-square");
  strictEqual(stat("df"), 1);
  close(stat("P value"), 0.4674, 1e-3, "P value");
  deepStrictEqual(
    out.survivalGroups!.map((g) => [g.group, g.median, g.subjects]),
    [
      ["Treated", 15, 5],
      ["Placebo", 8, 5],
    ],
  );
  // A renamed variable follows the params, and a gone one errors by name.
  deepStrictEqual(
    followTable(
      {
        ...analysis,
        analysisType: "survival",
        analysisParams: { curveTest: "logrank", correction: "holm", time: "Time", status: "Status", groupBy: "Group" },
      },
      { renamed: { Group: "Arm" } },
      [],
    ).analysisParams,
    { curveTest: "logrank", correction: "holm", time: "Time", status: "Status", groupBy: "Arm" },
  );
  deepStrictEqual(
    await runAnalysis("survival", data, {
      curveTest: "logrank",
      correction: "holm",
      time: "Time",
      status: "Status",
      groupBy: "Gone",
    }),
    { error: missingColumn("Gone") },
  );
  const bad: [TableData, string][] = [
    // A code that isn't 0 or 1.
    [
      { columns: ["Title", "Time", "Status", "Group"], rows: [[null, "3", "2", "Treated"], [null, "5", "1", "Placebo"]] },
      "enter 1 for an event, 0 for a censored subject",
    ],
    // A time of 0.
    [
      { columns: ["Title", "Time", "Status", "Group"], rows: [[null, "0", "1", "Treated"], [null, "5", "1", "Placebo"]] },
      "must be positive",
    ],
    // A grouping variable with one level.
    [
      { columns: ["Title", "Time", "Status", "Group"], rows: [[null, "3", "1", "Treated"], [null, "5", "1", "Treated"]] },
      "at least two levels",
    ],
    // No events anywhere.
    [
      { columns: ["Title", "Time", "Status", "Group"], rows: [[null, "3", "0", "Treated"], [null, "5", "0", "Placebo"]] },
      "No events were recorded",
    ],
  ];
  for (const [table, message] of bad) {
    const badOut = await runAnalysis("survival", table, {
      curveTest: "logrank",
      correction: "holm",
      time: "Time",
      status: "Status",
      groupBy: "Group",
    });
    if (!("error" in badOut) || !badOut.error.includes(message)) {
      throw new Error(`expected an error mentioning "${message}", got ${JSON.stringify(badOut).slice(0, 200)}`);
    }
  }
});

check("the survival analysis and Cox refuse a table with no events at all", async () => {
  // All subjects censored: the log-rank path used to return a meaningless
  // chi-square of 0 (P = 1), the Gehan path crashed in solve() on a singular
  // matrix, and Cox crashed subscripting cox.zph's empty table.
  const data = logRankTable(
    ["Title", "Days", "A", "B"],
    [
      ["", "3", "0", ""],
      ["", "5", "0", ""],
      ["", "7", "", "0"],
      ["", "8", "", "0"],
      ["", "10", "0", ""],
      ["", "12", "", "0"],
    ],
  );
  for (const curveTest of ["logrank", "gehan"] as const) {
    const out = await runAnalysis("survival", data, { curveTest, correction: "holm" });
    if (!("error" in out) || !out.error.includes("No events")) {
      throw new Error(`survival/${curveTest}: expected a "No events" error, got ${JSON.stringify(out).slice(0, 300)}`);
    }
  }
  const cox = await runAnalysis("cox", data, {});
  if (!("error" in cox) || !cox.error.includes("No events")) {
    throw new Error(`cox: expected a "No events" error, got ${JSON.stringify(cox).slice(0, 300)}`);
  }
});

check("a pairwise Gehan comparison with no events returns NA, not a crash", async () => {
  // Only group C holds events, so the A–B pair has none: its Gehan test used
  // to crash in solve() on a singular matrix and abort the whole analysis.
  const data = logRankTable(
    ["Title", "Days", "A", "B", "C"],
    [
      ["", "3", "0", "", ""],
      ["", "5", "0", "", ""],
      ["", "7", "", "0", ""],
      ["", "8", "", "0", ""],
      ["", "4", "", "", "1"],
      ["", "6", "", "", "1"],
      ["", "9", "", "", "0"],
    ],
  );
  const out = await runAnalysis("survival", data, { curveTest: "gehan", correction: "holm" });
  if ("error" in out) throw new Error(out.error);
  strictEqual(out.comparisons![0].p, null, "the event-less A–B pair is open");
  ok(out.comparisons![1].p !== null && out.comparisons![2].p !== null, "pairs with events still complete");
  ok(out.stats.find((s) => s.label === "Chi-square")?.value !== null, "the overall Gehan test still runs");
});

check("Cox regression leaves the proportional-hazards P open when a group is never at risk at an event time", async () => {
  // Group B's subjects are all censored before A's first event: cox.zph
  // used to crash subscripting its table and abort the whole regression.
  const data = logRankTable(
    ["Title", "Days", "A", "B"],
    [
      ["", "10", "1", ""],
      ["", "12", "1", ""],
      ["", "15", "0", ""],
      ["", "1", "", "0"],
      ["", "2", "", "0"],
      ["", "2", "", "0"],
    ],
  );
  const out = await runAnalysis("cox", data, {});
  if ("error" in out) throw new Error(out.error);
  strictEqual(
    out.stats.find((s) => s.label === "Proportional hazards test P")?.value,
    null,
    "cox.zph could not run on this fit",
  );
  strictEqual(out.hazardRatios?.length, 1, "one hazard ratio still reported");
});

check("frequency bins are right-closed with the first bin closed, and empty bins stay", () => {
  // On-edge values go into the bin below them; the minimum stays in the first bin.
  deepStrictEqual(
    computeFrequencyBins([2, 4, 6, 8], { binMode: "width", binWidth: 2, startAt: 2 }).bins.map((b) => b.count),
    [2, 1, 1],
  );
  // A gap leaves zero-count bins in place.
  deepStrictEqual(
    computeFrequencyBins([1, 2, 9, 10], { binMode: "width", binWidth: 2, startAt: 0 }).bins.map((b) => b.count),
    [2, 0, 0, 0, 2],
  );
  // Relative and cumulative frequencies sum to 1.
  const { bins } = computeFrequencyBins([2.1, 3.5, 3.9, 4.2, 5, 5.8, 6.1, 7.4, 8, 9.3], {
    binMode: "width",
    binWidth: 2,
    startAt: 2,
  });
  deepStrictEqual(
    bins.map((b) => [b.count, b.relativeFrequency, b.cumulativeCount, b.cumulativeFrequency]),
    [
      [3, 0.3, 3, 0.3],
      [3, 0.3, 6, 0.6],
      [3, 0.3, 9, 0.9],
      [1, 0.1, 10, 1],
    ],
  );
});

check("frequency bins put a value exactly on an edge into the bin below it, not above", () => {
  // (0.2 - 0.1) / 0.1 is 1 in doubles, so Math.floor alone puts 0.2 in
  // "(0.2, 0.3]"; the index is nudged against the actual edges until the
  // value lies inside its bin.
  const { bins } = computeFrequencyBins([0.1, 0.2, 0.3, 0.5], { binMode: "auto" });
  deepStrictEqual(
    bins.map((b) => [b.bin, b.count]),
    [
      ["[0.1, 0.2]", 2],
      ["(0.2, 0.3]", 1],
      ["(0.3, 0.4]", 0],
      ["(0.4, 0.5]", 1],
    ],
  );
});

check("pretty breaks stay distinct at large magnitudes instead of collapsing to NaN counts", () => {
  // toPrecision(12) rounded both ends of [1e9, 1e9+0.0005] to the same
  // value, collapsing start === end and producing NaN counts.
  deepStrictEqual(prettyBreaks(1e9, 1e9 + 0.0005, 5), [
    1000000000, 1000000000.0001, 1000000000.0002, 1000000000.0003, 1000000000.0004, 1000000000.0005,
  ]);
  const { bins } = computeFrequencyBins([1e9, 1e9 + 0.0005], { binMode: "auto" });
  deepStrictEqual(
    bins.map((b) => b.count),
    [1, 0, 1],
  );
  ok(bins.every((b) => Number.isFinite(b.count) && Number.isFinite(b.relativeFrequency)));
});

check("binCounts keeps a value exactly on the first edge at large magnitudes", () => {
  // fuzz = 1e-7 × median width is below half a ULP at 1e9, so the fuzzed
  // first edge rounds back to the edge itself; a strict `>` dropped the
  // value sitting on it. R's hist() counts it (include.lowest): [3, 1].
  const values = [1e9, 1e9 + 0.0002, 1e9 + 0.0005, 1e9 + 0.001];
  deepStrictEqual(binCounts(values, binEdges(values)), [3, 1]);
});

check("width-mode binning terminates when the width is below the rounding resolution at 1e9", () => {
  // clean(1e9 + 0.0002) rounded back to 1e9, so the old repeated-addition
  // loop pushed 1e9 forever (OOM/hang). Edges are built by index now, so
  // this returns 5,000 bins in milliseconds.
  const { bins, edges } = computeFrequencyBins([1e9, 1e9 + 1], { binMode: "width", binWidth: 0.0002 });
  strictEqual(bins.length, 5000);
  strictEqual(edges.length, 5001);
  strictEqual(edges[0], 1e9);
  strictEqual(edges.at(-1), 1e9 + 1);
  deepStrictEqual(
    bins.map((b) => b.count).filter((c) => c > 0),
    [1, 1],
  );
  strictEqual(
    bins.reduce((s, b) => s + b.count, 0),
    2,
  );
});

check("a constant column bins into one bin, and bad binning is an error, not a crash", async () => {
  const table = (values: (number | string)[]): TableData => ({
    columns: ["Title", "V"],
    rows: values.map((v) => [null, String(v)]),
  });
  const one = await runAnalysis("frequency-distribution", table([5, 5, 5]), { binMode: "auto" });
  if ("error" in one) throw new Error(one.error);
  deepStrictEqual(
    one.frequencyBins?.[0].bins.map((b) => [b.lower, b.upper, b.count]),
    [[0, 5, 3]],
  );
  for (const [params, message] of [
    [{ binMode: "width", binWidth: 0, startAt: 2 }, "greater than 0"],
    [{ binMode: "width", binWidth: -1, startAt: 2 }, "greater than 0"],
    [{ binMode: "count", binCount: 1, startAt: 2 }, "at least 2"],
    [{ binMode: "count", binCount: 2.5, startAt: 2 }, "at least 2"],
  ] as const) {
    const out = await runAnalysis("frequency-distribution", table([1, 2, 3]), params);
    if (!("error" in out) || !out.error.includes(message))
      throw new Error(`expected an error mentioning "${message}", got ${JSON.stringify(out)}`);
  }
  const few = await runAnalysis("frequency-distribution", table([5]), { binMode: "auto" });
  if (!("error" in few) || !few.error.includes("at least 2 values"))
    throw new Error(`expected the too-few-values error, got ${JSON.stringify(few)}`);
});

// v1.5.0 m14: the runner accepted up to 10,000 bins though plan 06 caps the
// count at 100 — a hand-built 500-bin request ran 500 bins. It now clamps to
// the plan maximum and says so in the notes (the file loader already clamps
// saved values the same way, FF-F16); the histogram graph draws from the
// same counter, so it is pinned here too.
check("frequency-distribution clamps binCount to the plan maximum of 100 (m14)", async () => {
  const table = (values: number[]): TableData => ({
    columns: ["Title", "V"],
    rows: values.map((v) => [null, String(v)]),
  });
  const values = [2.1, 3.5, 3.9, 4.2, 5, 5.8, 6.1, 7.4, 8, 9.3];
  const out = await runAnalysis("frequency-distribution", table(values), {
    binMode: "count",
    binCount: 500,
    startAt: 0,
  });
  if ("error" in out) throw new Error(out.error);
  strictEqual(out.frequencyBins?.[0].bins.length, 100);
  ok(
    out.notes.includes("500") && out.notes.includes("100"),
    `notes should say the request was clamped, got: ${out.notes}`,
  );
  strictEqual(
    out.frequencyBins?.[0].bins.reduce((s, b) => s + b.count, 0),
    values.length,
    "the clamped bins still cover every value",
  );
  // The graph's shared counter clamps the same way, so it can never draw
  // more bins than the analysis reports.
  strictEqual(computeFrequencyBins(values, { binMode: "count", binCount: 500, startAt: 0 }).bins.length, 100);
  // 100 stays 100, and an in-range request says nothing about clamping.
  const hundred = await runAnalysis("frequency-distribution", table(values), {
    binMode: "count",
    binCount: 100,
    startAt: 0,
  });
  if ("error" in hundred) throw new Error(hundred.error);
  strictEqual(hundred.frequencyBins?.[0].bins.length, 100);
  ok(!hundred.notes.includes("clamped"), "an in-range request says nothing about clamping");
});

// v1.5.0 F5: the bin-count question carried min 2 / max 100 as input hints
// only — no `validate`, so 1 sailed through to a runner error after Run and
// 101–10000 were silently accepted. The wizard now blocks both before Run.
check("the frequency wizard validates the bin count as a whole number from 2 to 100 (F5)", () => {
  const table = readTable({
    columns: ["Title", "V"],
    rows: [["", "2.1"], ["", "3.5"], ["", "5"], ["", "7.4"], ["", "9.3"]],
  });
  const binCount = WIZARDS["frequency-distribution"]!
    .questions({ binMode: "count" }, table)
    .filter(Boolean)
    .find((q) => (q as Question).id === "binCount") as Question;
  if (binCount.kind !== "number") throw new Error("binCount is not a number question");
  strictEqual(binCount.min, 2);
  strictEqual(binCount.max, 100);
  const message = "The number of bins must be a whole number between 2 and 100.";
  strictEqual(binCount.validate?.(1), message);
  strictEqual(binCount.validate?.(101), message);
  strictEqual(binCount.validate?.(500), message);
  strictEqual(binCount.validate?.(2.5), message);
  strictEqual(binCount.validate?.(2), undefined);
  strictEqual(binCount.validate?.(100), undefined);
});

