check("m20 non-finite numeric params are refused with a clean error", async () => {
  // All three params are wizard-validated in practice, so this is
  // defense-in-depth for a hand-edited file: before the fix λ = ∞ reached R
  // as the bare word "Infinity" ("object 'Infinity' not found"), a NaN AUC
  // baseline ran and returned a null area labelled "baseline Y = NaN", and
  // a NaN frequency startAt crashed with "Invalid array length".
  const xy: TableData = {
    columns: ["Title", "X", "Response"],
    rows: [
      [null, "1", "1.4"],
      [null, "2", "1.9"],
      [null, "3", "3.6"],
      [null, "4", "3.8"],
      [null, "5", "5.5"],
      [null, "6", "5.7"],
      [null, "7", "7.4"],
      [null, "8", "7.6"],
      [null, "9", "9.5"],
      [null, "10", "9.8"],
    ],
  };
  for (const lambda of [Infinity, -Infinity, NaN]) {
    const r = await runAnalysis("deming-regression", xy, { y: "Response", lambda });
    if (!("error" in r) || !r.error.includes("finite"))
      throw new Error(`deming lambda=${lambda}: ${"error" in r ? r.error : "ran"}, expected a finite-number error`);
  }
  // The graph overlay's closed form shares the same guard: λ = ∞ gave a
  // NaN slope instead of no fit.
  strictEqual(fitDeming([1, 2, 3], [1.4, 1.9, 3.6], Infinity), null, "fitDeming with λ = ∞ should be null");
  strictEqual(fitDeming([1, 2, 3], [1.4, 1.9, 3.6], NaN), null, "fitDeming with λ = NaN should be null");
  for (const baseline of [NaN, Infinity]) {
    const r = await runAnalysis("area-under-curve", xy, { baseline });
    if (!("error" in r) || !r.error.includes("finite"))
      throw new Error(`AUC baseline=${baseline}: ${"error" in r ? r.error : "ran"}, expected a finite-number error`);
  }
  const col: TableData = {
    columns: ["Title", "A"],
    rows: [
      [null, "1.2"],
      [null, "2.5"],
      [null, "3.1"],
      [null, "4.7"],
      [null, "5.0"],
      [null, "6.3"],
    ],
  };
  for (const startAt of [NaN, Infinity]) {
    const r = await runAnalysis("frequency-distribution", col, { binMode: "width", binWidth: 1, startAt });
    if (!("error" in r) || !r.error.includes("finite"))
      throw new Error(`frequency startAt=${startAt}: ${"error" in r ? r.error : "ran"}, expected a finite-number error`);
  }
});

check("seq 202 AUC peak options: ignore small peaks, peaks above baseline only", async () => {
  // Prism's AUC dialog: ignore peaks under X% of the Y range, and count only
  // peaks above the baseline. Expected areas are hand-computed trapezoids
  // (verified in Python before the check was written), not runner outputs:
  // X 0..6, Y 0,1,0,5,0,2,0 — peaks of height 1, 5, 2 above baseline 0,
  // Y range 5; default area 8.0.
  const peaks: TableData = {
    columns: ["Title", "X", "Y"],
    rows: [
      [null, "0", "0"],
      [null, "1", "1"],
      [null, "2", "0"],
      [null, "3", "5"],
      [null, "4", "0"],
      [null, "5", "2"],
      [null, "6", "0"],
    ],
  };
  const areaOf = async (params: Record<string, unknown>) => {
    const r = await runAnalysis("area-under-curve", peaks, params);
    if ("error" in r) throw new Error(r.error);
    return r.areas?.[0]?.area;
  };
  strictEqual(await areaOf({ baseline: 0 }), 8, "default AUC should be 8");
  strictEqual(await areaOf({ baseline: 0, ignorePeaksBelow: 30 }), 7, "30% threshold (1.5) drops only the height-1 peak");
  strictEqual(await areaOf({ baseline: 0, ignorePeaksBelow: 50 }), 5, "50% threshold (2.5) drops the height-1 and height-2 peaks");
  strictEqual(await areaOf({ baseline: 0, ignorePeaksBelow: 0 }), 8, "0% keeps every peak");
  // Baseline 1: heights -1,0,-1,4,-1,1,-1; default area 2.0; the 30% threshold
  // (1.5 of the 5 range) drops the height-1 peak at X=5, area 1.0.
  strictEqual(await areaOf({ baseline: 1 }), 2, "baseline 1 default AUC should be 2");
  strictEqual(await areaOf({ baseline: 1, ignorePeaksBelow: 30 }), 1, "baseline 1 + 30% drops the height-1 peak");
  // A dip below the baseline: X 0..4, Y 0,3,-2,3,0 — default 4.0 (the dip
  // counts negative), peaks-above-baseline-only 6.0 (the dip counts zero).
  const dip: TableData = {
    columns: ["Title", "X", "Y"],
    rows: [
      [null, "0", "0"],
      [null, "1", "3"],
      [null, "2", "-2"],
      [null, "3", "3"],
      [null, "4", "0"],
    ],
  };
  const dipArea = async (params: Record<string, unknown>) => {
    const r = await runAnalysis("area-under-curve", dip, params);
    if ("error" in r) throw new Error(r.error);
    return r.areas?.[0]?.area;
  };
  strictEqual(await dipArea({ baseline: 0 }), 4, "dip default AUC should be 4");
  strictEqual(await dipArea({ baseline: 0, peaksAboveBaselineOnly: true }), 6, "peaks-above-baseline-only should be 6");
  // Out-of-range threshold is refused, not clamped.
  const bad = await runAnalysis("area-under-curve", peaks, { baseline: 0, ignorePeaksBelow: 150 });
  if (!("error" in bad) || !bad.error.includes("between 0 and 100"))
    throw new Error(`ignorePeaksBelow=150: ${"error" in bad ? bad.error : "ran"}, expected a 0–100 error`);
});

check("m21 per-series R² is null, not NaN, when the evaluator returns NaN", async () => {
  // A global fit whose closed-form evaluator returns NaN (e.g. a log of a
  // negative fitted value) made rSquared return NaN — JSON renders it as
  // null, but the in-memory outcome carried a real NaN, which the results
  // view would print as "NaN". The fit itself still runs; only the R² is
  // unknowable, so it is null like the constant-Y case.
  const g = await runGlobalFit(
    [{ name: "S", x: [1, 2, 3, 4, 5], y: [2, 4, 6, 8, 10], covariate: 0 }],
    {
      formula: "a+b*x",
      params: [
        { name: "a", shared: true, start: () => 0 },
        { name: "b", shared: true, start: () => 1 },
      ],
      evaluate: () => Math.sqrt(-1),
    },
  );
  strictEqual(g.perSeries[0].rSquared, null, "R² with a NaN evaluator should be null, not NaN");
  // And a finite evaluator still yields a real R²: the linear fit is exact.
  const good = await runGlobalFit(
    [{ name: "S", x: [1, 2, 3, 4, 5], y: [2, 4, 6, 8, 10], covariate: 0 }],
    {
      formula: "a+b*x",
      params: [
        { name: "a", shared: true, start: () => 0 },
        { name: "b", shared: true, start: () => 1 },
      ],
      evaluate: (coefficients, _series, _i, x) => {
        const a = coefficients.find((c) => c.term === "a")?.estimate ?? 0;
        const b = coefficients.find((c) => c.term === "b")?.estimate ?? 0;
        return a + b * x;
      },
    },
  );
  const goodR2 = good.perSeries[0].rSquared;
  if (goodR2 == null || Math.abs(goodR2 - 1) > 1e-9)
    throw new Error(`R² with an exact linear evaluator: ${goodR2}, expected 1`);
});

check("transform concentrations converts between molar units by exact powers of 1000", async () => {
  // Each molar step is ×1000, up and down the scale.
  strictEqual(concentrationFactor("µM", "nM"), 1000);
  strictEqual(concentrationFactor("M", "pM"), 1e12);
  strictEqual(concentrationFactor("nM", "µM"), 0.001);
  strictEqual(concentrationFactor("mM", "mM"), 1);
  strictEqual(convertConcentration(1, "µM", "nM"), 1000);
  strictEqual(convertConcentration(2.5, "mM", "µM"), 2500);
  strictEqual(convertConcentration(500, "nM", "µM"), 0.5);
  const table = (values: (number | string)[]): TableData => ({
    columns: ["Title", "Dose"],
    rows: values.map((v) => [null, String(v)]),
  });
  const out = await runAnalysis("transform-concentrations", table([1, 2.5]), {
    column: "Dose",
    fromUnit: "µM",
    toUnit: "nM",
  });
  if ("error" in out) throw new Error(out.error);
  deepStrictEqual(
    out.convertedColumns?.[0].values.map((v) => [v.row, v.original, v.converted]),
    [
      [1, 1, 1000],
      [2, 2.5, 2500],
    ],
  );
  // The source column is untouched: the table still holds the originals.
  deepStrictEqual(readTable(table([1, 2.5])).columns[0].values, [1, 2.5]);
  // A column with no numeric values, and a column that is gone, are clean
  // errors — and a non-numeric cell is skipped and counted in the notes,
  // not converted.
  const noNumbers = await runAnalysis("transform-concentrations", table(["abc"]), {
    column: "Dose",
    fromUnit: "µM",
    toUnit: "nM",
  });
  if (!("error" in noNumbers) || !noNumbers.error.includes("no numeric values"))
    throw new Error(`expected the no-numeric-values error, got ${JSON.stringify(noNumbers)}`);
  const gone = await runAnalysis("transform-concentrations", table([1]), {
    column: "Gone",
    fromUnit: "µM",
    toUnit: "nM",
  });
  if (!("error" in gone) || !gone.error.includes("no longer in the table"))
    throw new Error(`expected the missing-column error, got ${JSON.stringify(gone)}`);
  const mixed = await runAnalysis("transform-concentrations", table([1, "abc", 2]), {
    column: "Dose",
    fromUnit: "µM",
    toUnit: "nM",
  });
  if ("error" in mixed) throw new Error(mixed.error);
  deepStrictEqual(
    mixed.convertedColumns?.[0].values.map((v) => v.converted),
    [1000, 2000],
  );
  ok(mixed.notes.includes("1 non-numeric cell ignored"));
});

check("Sturges, pretty breaks and nice widths match R's rules", () => {
  strictEqual(sturgesCount(10), 5);
  strictEqual(sturgesCount(2), 2);
  // pretty() may return fewer intervals than asked for: 4, not 5, on 2.1–9.3.
  deepStrictEqual(prettyBreaks(2.1, 9.3, 5), [2, 4, 6, 8, 10]);
  deepStrictEqual(prettyBreaks(0, 10, 5), [0, 2, 4, 6, 8, 10]);
  deepStrictEqual(prettyBreaks(123, 456, 5), [100, 150, 200, 250, 300, 350, 400, 450, 500]);
  // A ratio a hair from a whole number counts as that number (0.3 / 0.1).
  deepStrictEqual(prettyBreaks(0.3, 0.9, 5), [0.3, 0.4, 0.5, 0.6, 0.7, 0.8, 0.9]);
  strictEqual(niceWidthUp(1.44), 2);
  strictEqual(niceWidthUp(2), 2);
  strictEqual(niceWidthUp(2.01), 5);
  strictEqual(niceWidthUp(0.06), 0.1);
});

