check("select and transform refuses bad inputs with clear errors", async () => {
  // A column renamed away after the wizard ran is caught before the runner.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, { columns: ["Age", "Gone"] }),
    { error: "“Gone” is no longer in the table — run the analysis again and pick the variables." },
  );
  // A transform needs numbers.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      transforms: [{ variable: "Sex", kind: "log10" }],
    }),
    { error: "“Sex” holds no numbers yet — pick a variable with numbers in it." },
  );
  // A transform that needs a constant, without one.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      transforms: [{ variable: "Weight", kind: "multiply" }],
    }),
    { error: "The “multiply” transform of “Weight” needs a constant — enter a value for K." },
  );
  // An unknown transform kind.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      transforms: [{ variable: "Score", kind: "bogus" as never }],
    }),
    {
      error:
        "“bogus” is not a transform — pick one of: log10, ln, log2, reciprocal, sqrt, square, exp, pow10, negate, abs, multiply, divide, add, subtract, power, round, min, max, mean, stdev, stderr.",
    },
  );
  // A formula that cannot be read.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      equations: [{ name: "Bad", formula: "Weight +" }],
    }),
    { error: "“Weight +” could not be read: the formula ends before a value." },
  );
  // A formula naming a variable the table does not hold.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      equations: [{ name: "Bad", formula: "Gone * 2" }],
    }),
    { error: "unknown variable “Gone” — the table has no variable with that name." },
  );
  // A new variable colliding with one the new table already has.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      equations: [{ name: "Age", formula: "Score * 2" }],
    }),
    { error: "“Age” is already in the new table — a new variable needs a different name." },
  );
  // A range that starts after it ends, and one outside the table.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, { rowRange: { first: 4, last: 2 } }),
    { error: "The first row (4) comes after the last row (2) — pick a range that starts first." },
  );
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, { rowRange: { first: 0, last: 2 } }),
    { error: "Row 0 is not in the table — rows run from 1 to 5." },
  );
  // A filter that leaves no rows.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      rowFilter: { variable: "Score", operator: ">", value: 100 },
    }),
    { error: "No rows are left after the selection — loosen the row filter or range." },
  );
  // A column filter comparing a variable with itself.
  deepStrictEqual(
    await runAnalysis("select-transform", SELECT_TABLE, {
      columnFilter: { variable: "Score", operator: ">", otherVariable: "Score" },
    }),
    { error: "The two variables must be different — pick two different variables." },
  );
  // MCP-side validation: a valid call passes, a bad transform kind does not.
  deepStrictEqual(
    validateAnalysisParams("select-transform", {
      columns: ["Age"],
      transforms: [{ variable: "Score", kind: "log10" }],
      rowRange: { first: 1, last: 3 },
    }).errors,
    [],
  );
  strictEqual(
    validateAnalysisParams("select-transform", {
      transforms: [{ variable: "Score", kind: "bogus" }],
    }).errors.length,
    1,
  );
  ok(
    validateAnalysisParams("select-transform", {
      transforms: [{ variable: "Score", kind: "bogus" }],
    }).errors[0].includes("log10"),
  );
  // A wizard drives it: columns, range, value filter, one transform, one equation.
  const wizard = WIZARDS["select-transform"];
  ok(wizard);
  deepStrictEqual(
    wizard!.finish(
      {
        columns: ["Age", "Score"],
        rowScope: "range",
        firstRow: 2,
        lastRow: 5,
        valueFilterVariable: "Score",
        valueFilterOperator: ">",
        valueFilterValue: 6,
        columnFilterVariable: "none",
        transform0Variable: "Score",
        transform0Kind: "log10",
        transform0Title: "",
        transform0Another: "no",
        equation0: "Double = Score * 2",
        equation0Another: "no",
      },
      readTable(SELECT_TABLE),
    ),
    {
      type: "select-transform",
      params: {
        columns: ["Age", "Score"],
        rowRange: { first: 2, last: 5 },
        rowFilter: { variable: "Score", operator: ">", value: 6 },
        transforms: [{ variable: "Score", kind: "log10" }],
        equations: [{ name: "Double", formula: "Score * 2" }],
      },
    },
  );
  // The wizard's questions follow the answers: a range asks for its ends, a
  // picked transform asks for its kind, title and whether there is another.
  deepStrictEqual(
    wizard!
      .questions(
        {
          columns: ["Age", "Score"],
          rowScope: "range",
          valueFilterVariable: "Score",
          columnFilterVariable: "none",
          transform0Variable: "Score",
          equation0: "",
        },
        readTable(SELECT_TABLE),
        "multiple",
      )
      .filter(Boolean)
      .map((q) => (q as Question).id),
    [
      "columns",
      "rowScope",
      "firstRow",
      "lastRow",
      "valueFilterVariable",
      "valueFilterOperator",
      "valueFilterValue",
      "columnFilterVariable",
      "transform0Variable",
      "transform0Kind",
      "transform0Title",
      "transform0Another",
      "equation0",
    ],
  );
});

// Prune rows (v2): drop rows matching a condition — empty, below a
// threshold, above a threshold, or outside a range — from the chosen
// columns, listing what was dropped; the source table is never touched.
check("prune rows drops empty rows and lists what was dropped", async () => {
  const table: TableData = {
    columns: ["Title", "A", "B"],
    rows: [
      ["", "4", "2"],
      ["", "10", "8"],
      ["", "", ""],
      ["", "7", ""],
      ["", "", "20"],
    ],
  };
  const out = await runAnalysis("prune-rows", table, { ys: ["A", "B"], condition: "empty" });
  if ("error" in out) throw new Error(out.error);
  strictEqual(out.testType, "prune-rows");
  strictEqual(out.subtitle, "Prune rows (empty rows)");
  deepStrictEqual(
    out.stats.map((s) => [s.label, s.value]),
    [
      ["Rows in table", 5],
      ["Rows kept", 4],
      ["Rows pruned", 1],
    ],
  );
  deepStrictEqual(out.prunedRows?.columns, ["A", "B"]);
  deepStrictEqual(
    out.prunedRows?.kept.map((r) => [r.row, r.values]),
    [
      ["Row 1", [4, 2]],
      ["Row 2", [10, 8]],
      ["Row 4", [7, null]],
      ["Row 5", [null, 20]],
    ],
  );
  deepStrictEqual(
    out.prunedRows?.pruned.map((r) => [r.row, r.values]),
    [["Row 3", [null, null]]],
  );
  ok(out.notes.includes("held no value in any chosen data set"));
  ok(out.notes.includes("Row 3"));
  ok(out.notes.includes("The original table is unchanged"));
  // The descriptives are of the kept values, not the originals.
  deepStrictEqual(
    out.groups.map((g) => [g.name, g.mean, g.n]),
    [
      ["A", 7, 3],
      ["B", 10, 3],
    ],
  );
});

check("prune rows drops rows below, above, or outside a threshold, and errors clearly", async () => {
  const table: TableData = {
    columns: ["Title", "A", "B"],
    rows: [
      ["", "4", "2"],
      ["", "10", "8"],
      ["", "", ""],
      ["", "7", ""],
      ["", "", "20"],
    ],
  };
  // Below: a row is dropped when every value it holds is below the
  // threshold — a row holding no value at all is kept (use "empty" for it).
  const below = await runAnalysis("prune-rows", table, { ys: ["A", "B"], condition: "below", threshold: 9 });
  if ("error" in below) throw new Error(below.error);
  deepStrictEqual(
    below.prunedRows?.pruned.map((r) => r.row),
    ["Row 1", "Row 4"],
  );
  deepStrictEqual(
    below.prunedRows?.kept.map((r) => r.row),
    ["Row 2", "Row 3", "Row 5"],
  );
  deepStrictEqual(
    below.groups.map((g) => [g.name, g.mean, g.n]),
    [
      ["A", 10, 1],
      ["B", 14, 2],
    ],
  );
  // Above: only the row whose every value is above the threshold goes.
  const above = await runAnalysis("prune-rows", table, { ys: ["A", "B"], condition: "above", threshold: 9 });
  if ("error" in above) throw new Error(above.error);
  deepStrictEqual(
    above.prunedRows?.pruned.map((r) => r.row),
    ["Row 5"],
  );
  // Outside: every held value below the low end or above the high end.
  const outside = await runAnalysis("prune-rows", table, {
    ys: ["A", "B"],
    condition: "outside",
    low: 5,
    high: 15,
  });
  if ("error" in outside) throw new Error(outside.error);
  deepStrictEqual(
    outside.prunedRows?.pruned.map((r) => r.row),
    ["Row 1", "Row 5"],
  );
  // An XY table carries X into the kept and pruned rows.
  const xy: TableData = {
    columns: ["Title", "Time", "Y1", "Y2"],
    rows: [
      ["", "0", "10", "5"],
      ["", "1", "", ""],
      ["", "2", "14", "9"],
    ],
  };
  const xyOut = await runAnalysis("prune-rows", xy, { ys: ["Y1", "Y2"], x: "Time", condition: "empty" });
  if ("error" in xyOut) throw new Error(xyOut.error);
  deepStrictEqual(
    xyOut.prunedRows?.pruned.map((r) => [r.row, r.x]),
    [["Row 2", 1]],
  );
  deepStrictEqual(
    xyOut.prunedRows?.kept.map((r) => r.x),
    [0, 2],
  );
  // Errors name the problem instead of dropping something wrong.
  deepStrictEqual(await runAnalysis("prune-rows", table, { ys: ["A"], condition: "below" }), {
    error: "Enter a threshold value to prune against.",
  });
  deepStrictEqual(
    await runAnalysis("prune-rows", table, { ys: ["A"], condition: "outside", low: 10, high: 5 }),
    { error: "The range's low end (10) must be below its high end (5)." },
  );
  deepStrictEqual(
    await runAnalysis(
      "prune-rows",
      { columns: ["Title", "A"], rows: [["", "1"], ["", "2"]] },
      { ys: ["A"], condition: "below", threshold: 10 },
    ),
    { error: "Every row matches the condition, so no rows would be kept." },
  );
  deepStrictEqual(await runAnalysis("prune-rows", table, { ys: ["A"], condition: "nope" as never }), {
    error: "Unknown prune condition: “nope”.",
  });
  deepStrictEqual(await runAnalysis("prune-rows", table, { ys: ["Nope"], condition: "empty" }), {
    error: "The column “Nope” is no longer in the table. Create this analysis again to choose another.",
  });
});

