check("descriptive statistics reports sum, moment skewness and excess kurtosis, pinned by hand", async () => {
  // Skewness is the moment coefficient g1 = m3/m2^1.5 and kurtosis is the excess
  // b2 − 3 = m4/m2^2 − 3 (a normal distribution is ~0); both are NA under 3 values
  // or on a constant column. Values below are hand-computed (exact rational arithmetic).
  const table: TableData = {
    columns: ["Title", "Skewed", "Symmetric", "Pair", "Constant"],
    rows: [
      ["", "1", "1", "4", "5"],
      ["", "2", "2", "6", "5"],
      ["", "2", "3", "", "5"],
      ["", "3", "4", "", "5"],
      ["", "3", "5", "", "5"],
      ["", "3", "", "", "5"],
      ["", "4", "", "", "5"],
      ["", "4", "", "", "5"],
      ["", "5", "", "", "5"],
      ["", "10", "", "", "5"],
    ],
  };
  const out = await runAnalysis("descriptive-statistics", table);
  if ("error" in out) throw new Error(`descriptive statistics should run, got ${out.error}`);
  const [skewed, symmetric, pair, constant] = out.groups;
  const close = (got: number | null | undefined, want: number, label: string) => {
    if (got == null || Math.abs(got - want) > 1e-9) throw new Error(`${label}: got ${got}, by hand ${want}`);
  };
  close(skewed.sum, 37, "Skewed sum");
  close(skewed.skewness, 1.6689330728161373, "Skewed skewness");
  close(skewed.kurtosis, 2.238725728502388, "Skewed kurtosis");
  close(symmetric.sum, 15, "Symmetric sum");
  close(symmetric.skewness, 0, "Symmetric skewness");
  close(symmetric.kurtosis, -1.3, "Symmetric kurtosis");
  // Two values still sum, but have no skewness or kurtosis; a constant column has none either.
  close(pair.sum, 10, "Pair sum");
  if (pair.skewness != null || pair.kurtosis != null)
    throw new Error(`Pair skewness/kurtosis should be null, got ${pair.skewness}, ${pair.kurtosis}`);
  close(constant.sum, 50, "Constant sum");
  if (constant.skewness != null || constant.kurtosis != null)
    throw new Error(`Constant skewness/kurtosis should be null, got ${constant.skewness}, ${constant.kurtosis}`);
});

// Tauri v2 `#[tauri::command]` renames args to camelCase by default, so a
// Rust param `prefer_byo` must be invoked as `preferByo` — the cloud
// wrappers sent snake_case keys, and every multi-word cloud invoke failed
// at runtime with "missing required key preferByo" (broker Mac GUI proof,
// attempt 3: the "Always use my own Box app" checkbox never flipped).
// Rust tests cannot catch this class: they call the Rust fns directly,
// bypassing IPC arg mapping. Pin the JS-side keys here, and cross-check
// them against the Rust signatures so a renamed param fails this check
// instead of failing silently on the Mac.
check("cloud invokes send camelCase arg keys, matching the Rust command params (broker IPC)", () => {
  const native = readFileSync("src/native.ts", "utf8");
  const main = readFileSync("src-tauri/src/main.rs", "utf8");
  // Every multi-word key the cloud wrappers must send, and the Rust param
  // it maps from (snake_case in Rust, camelCase over IPC).
  const expected: [string, string][] = [
    ["preferByo", "prefer_byo"],
    ["clientId", "client_id"],
    ["clientSecret", "client_secret"],
    ["accountId", "account_id"],
    ["folderId", "folder_id"],
    ["fileId", "file_id"],
    ["expectedVersion", "expected_version"],
    ["parentId", "parent_id"],
    ["newParentId", "new_parent_id"],
    ["isFolder", "is_folder"],
  ];
  for (const [camel, snake] of expected) {
    ok(new RegExp(`\\b${camel}\\b`).test(native), `native.ts must send { ${camel} } for cloud commands`);
    ok(new RegExp(`\\b${snake}\\b`).test(main), `main.rs must still declare the Rust param ${snake}`);
  }
  // No snake_case key may survive inside any cloud invoke's arg object.
  // (Keys only: the values are the wrappers' own snake_case parameters,
  // which are untouched — only the IPC keys change.)
  const cloudInvokes = [...native.matchAll(/invoke<[^>]*>\("cloud_[a-z_]+", \{([^}]*)\}\)/g)];
  ok(cloudInvokes.length > 0, "native.ts must still have cloud invokes to check");
  for (const [, args] of cloudInvokes) {
    const keys = args.split(",").map((part) => part.split(":")[0].trim());
    const bad = keys.filter((key) => /[a-z]+_[a-z]/.test(key));
    ok(bad.length === 0, `cloud invoke arg keys must be camelCase, found snake_case key(s) ${bad.join(", ")} in { ${args.trim()} }`);
  }
});

// ── Wand (plan 37) ───────────────────────────────────────────────────────
// Apply an example table's analyses + graphs to new tables, batch. The
// planner is pure (src/lib/wand.ts), so these pins drive applyWand directly
// with a deterministic idGen; one pin goes through the store's applyWand
// action + undo, and one through a save/load round-trip.

const wandIdGen = () => {
  let n = 0;
  return (type: "analysis" | "graph") => `${type}_${++n}`;
};
const wandColumnTable = (id: string, name: string, columns: string[] = ["A", "B"]): ProjectNode => ({
  id,
  type: "table",
  name,
  parentId: null,
  tableType: "column",
  data: treatments(columns),
});
const twoGroupsParams = { paired: false, gaussian: true, equalVariance: true, ratio: false, tails: "two-sided" } as const;

check("Wand copies an example's analyses to a new table, params deep-copied", () => {
  const nodes: Record<string, ProjectNode> = {
    ex: wandColumnTable("ex", "Experiment 1"),
    a1: { id: "a1", type: "analysis", name: "Descriptives", parentId: "ex", analysisType: "descriptive-statistics" },
    a2: {
      id: "a2",
      type: "analysis",
      name: "Two groups",
      parentId: "ex",
      analysisType: "compare-two-groups",
      analysisParams: { ...twoGroupsParams },
    },
    t1: wandColumnTable("t1", "Experiment 2"),
  };
  const childOrder = { ex: ["a1", "a2"], t1: [] };
  const result = applyWand({ nodes, childOrder }, "ex", ["t1"], "", wandIdGen());
  strictEqual(result.report.created.length, 1);
  strictEqual(result.report.created[0].analyses, 2);
  strictEqual(result.report.created[0].graphs, 0);
  strictEqual(result.report.skipped.length, 0);
  const [c1, c2] = result.childOrder.t1;
  strictEqual(result.nodes[c1].analysisType, "descriptive-statistics");
  strictEqual(result.nodes[c2].analysisType, "compare-two-groups");
  strictEqual(result.nodes[c1].name, "Descriptives");
  strictEqual(result.nodes[c2].name, "Two groups");
  deepStrictEqual(result.nodes[c2].analysisParams, nodes.a2.analysisParams);
  // Mutating the copy's params leaves the example's untouched: deep copy, not a reference.
  (result.nodes[c2].analysisParams as { paired: boolean }).paired = true;
  strictEqual((nodes.a2.analysisParams as { paired: boolean }).paired, false);
  strictEqual(result.firstCreatedId, c1);
  ok(wandReportMessage(result.report).includes("2 analyses"));
});

check("Wand remaps a graph's linked analysis to the new copy and drops a dangling link", () => {
  const nodes: Record<string, ProjectNode> = {
    ex: { id: "ex", type: "table", name: "Clusters", parentId: null, tableType: "multiple", data: treatments(["V1", "V2"]) },
    a1: { id: "a1", type: "analysis", name: "K-means", parentId: "ex", analysisType: "k-means", analysisParams: { clusters: 3 } },
    g1: {
      id: "g1",
      type: "graph",
      name: "Cluster plot",
      parentId: "ex",
      graphType: "kmeans-scatter",
      graphOptions: { ...newGraphOptions("kmeans-scatter"), kmeansAnalysisId: "a1" },
    },
    g2: {
      id: "g2",
      type: "graph",
      name: "PCA plot",
      parentId: "ex",
      graphType: "pca-biplot",
      graphOptions: { ...newGraphOptions("pca-biplot"), pcaAnalysisId: "ghost" },
    },
    t1: { id: "t1", type: "table", name: "Clusters 2", parentId: null, tableType: "multiple", data: treatments(["V1", "V2"]) },
  };
  const childOrder = { ex: ["a1", "g1", "g2"], t1: [] };
  const result = applyWand({ nodes, childOrder }, "ex", ["t1"], "", wandIdGen());
  strictEqual(result.report.created[0].analyses, 1);
  strictEqual(result.report.created[0].graphs, 2);
  const [na, ng1, ng2] = result.childOrder.t1;
  ok(na !== "a1");
  strictEqual(result.nodes[ng1].graphOptions!.kmeansAnalysisId, na);
  ok(!("pcaAnalysisId" in (result.nodes[ng2].graphOptions ?? {})));
});

check("Wand skips a target whose table type the example's tests don't fit", () => {
  const xy = (id: string, name: string): ProjectNode => ({
    id,
    type: "table",
    name,
    parentId: null,
    tableType: "xy",
    data: treatments(["X", "Y1"]),
  });
  const nodes: Record<string, ProjectNode> = {
    ex: xy("ex", "Dose-response"),
    a1: {
      id: "a1",
      type: "analysis",
      name: "Fit",
      parentId: "ex",
      analysisType: "linear-regression",
      analysisParams: { y: "Y1", forceOrigin: true },
    },
    g1: { id: "g1", type: "graph", name: "Plot", parentId: "ex", graphType: "xy-scatter", graphOptions: newGraphOptions("xy-scatter") },
    t1: wandColumnTable("t1", "Column target"),
    t2: xy("t2", "XY target"),
  };
  const childOrder = { ex: ["a1", "g1"], t1: [], t2: [] };
  const result = applyWand({ nodes, childOrder }, "ex", ["t1", "t2"], "", wandIdGen());
  strictEqual(result.report.created.length, 1);
  strictEqual(result.report.created[0].tableId, "t2");
  strictEqual(result.report.created[0].analyses, 1);
  strictEqual(result.report.created[0].graphs, 1);
  strictEqual(result.report.skipped.length, 1);
  strictEqual(result.report.skipped[0].tableId, "t1");
  ok(/none of its analyses or graphs apply/.test(result.report.skipped[0].reason));
  strictEqual(result.childOrder.t1.length, 0);
});

check("Wand refuses an example with nothing to copy", () => {
  const nodes: Record<string, ProjectNode> = { ex: wandColumnTable("ex", "Empty"), t1: wandColumnTable("t1", "Target") };
  throws(() => applyWand({ nodes, childOrder: { ex: [], t1: [] } }, "ex", ["t1"]), /has no analyses or graphs to copy/);
});

check("Wand prefixes new sheet names and uniquifies a collision", () => {
  const nodes: Record<string, ProjectNode> = {
    ex: wandColumnTable("ex", "Experiment 1"),
    a1: { id: "a1", type: "analysis", name: "Desc", parentId: "ex", analysisType: "descriptive-statistics" },
    t1: wandColumnTable("t1", "Experiment 2"),
    old: { id: "old", type: "analysis", name: "* Desc", parentId: "t1", analysisType: "descriptive-statistics" },
  };
  const childOrder = { ex: ["a1"], t1: ["old"] };
  const result = applyWand({ nodes, childOrder }, "ex", ["t1"], "* ", wandIdGen());
  strictEqual(result.childOrder.t1.length, 2);
  strictEqual(result.nodes[result.childOrder.t1[1]].name, "* Desc 2");
});

check("Wand reports a target with no numeric data and one undo step removes every copy", () => {
  const nodes: Record<string, ProjectNode> = {
    ex: wandColumnTable("ex", "Experiment 1"),
    a1: { id: "a1", type: "analysis", name: "Desc", parentId: "ex", analysisType: "descriptive-statistics" },
    t1: wandColumnTable("t1", "Experiment 2"),
    t2: { id: "t2", type: "table", name: "Empty", parentId: null, tableType: "column", data: { columns: ["Title", "A", "B"], rows: [] } },
  };
  const childOrder = { ex: ["a1"], t1: [], t2: [] };
  const result = applyWand({ nodes, childOrder }, "ex", ["t1", "t2"], "", wandIdGen());
  strictEqual(result.report.created.length, 1);
  strictEqual(result.report.created[0].tableId, "t1");
  strictEqual(result.report.skipped.length, 1);
  strictEqual(result.report.skipped[0].tableId, "t2");
  strictEqual(result.report.skipped[0].reason, "has no numeric data");
  // Reducer round-trip: the same content through the store's applyWand action, then one undo.
  const base = { ...makeInitialState(), nodes, rootOrder: ["ex", "t1", "t2"], childOrder, activeNodeId: "ex" };
  let s = reducer(base, { type: "applyWand", nodes: result.nodes, childOrder: result.childOrder, activeNodeId: result.firstCreatedId });
  strictEqual(s.childOrder.t1.length, 1);
  strictEqual(s.activeNodeId, result.firstCreatedId);
  s = reducer(s, { type: "undo" });
  deepStrictEqual(s.nodes, nodes);
  deepStrictEqual(s.childOrder, childOrder);
});

check("Wand notes an analysis its target is too narrow for and still copies the rest", () => {
  const nodes: Record<string, ProjectNode> = {
    ex: wandColumnTable("ex", "Experiment 1"),
    a1: { id: "a1", type: "analysis", name: "Desc", parentId: "ex", analysisType: "descriptive-statistics" },
    a2: {
      id: "a2",
      type: "analysis",
      name: "Two groups",
      parentId: "ex",
      analysisType: "compare-two-groups",
      analysisParams: { ...twoGroupsParams },
    },
    t1: { id: "t1", type: "table", name: "One column", parentId: null, tableType: "column", data: treatments(["A"]) },
  };
  const childOrder = { ex: ["a1", "a2"], t1: [] };
  const result = applyWand({ nodes, childOrder }, "ex", ["t1"], "", wandIdGen());
  strictEqual(result.report.created.length, 1);
  strictEqual(result.report.created[0].analyses, 1);
  strictEqual(result.report.created[0].notes.length, 1);
  ok(/Compare two groups.*needs at least 2 columns/.test(result.report.created[0].notes[0]));
});

check("Wand copies survive a save/load round-trip with the remapped link intact", () => {
  const nodes: Record<string, ProjectNode> = {
    ex: { id: "ex", type: "table", name: "Clusters", parentId: null, tableType: "multiple", data: treatments(["V1", "V2"]) },
    a1: { id: "a1", type: "analysis", name: "K-means", parentId: "ex", analysisType: "k-means", analysisParams: { clusters: 3 } },
    g1: {
      id: "g1",
      type: "graph",
      name: "Cluster plot",
      parentId: "ex",
      graphType: "kmeans-scatter",
      graphOptions: { ...newGraphOptions("kmeans-scatter"), kmeansAnalysisId: "a1" },
    },
    t1: { id: "t1", type: "table", name: "Clusters 2", parentId: null, tableType: "multiple", data: treatments(["V1", "V2"]) },
  };
  const childOrder = { ex: ["a1", "g1"], t1: [] };
  const result = applyWand({ nodes, childOrder }, "ex", ["t1"], "", wandIdGen());
  const [na, ng1] = result.childOrder.t1;
  const payload: ProjectFilePayload = {
    nodes: result.nodes,
    rootOrder: ["ex", "t1"],
    childOrder: result.childOrder,
    activeNodeId: result.firstCreatedId,
  };
  const back = read(serializeProjectFile(payload));
  strictEqual(back.project.nodes[na].analysisType, "k-means");
  strictEqual(back.project.nodes[ng1].graphOptions!.kmeansAnalysisId, na);
});

check("Wand offers only tables with analyses or graphs as examples, never the target", () => {
  const nodes: Record<string, ProjectNode> = {
    ex: wandColumnTable("ex", "Experiment 1"),
    a1: { id: "a1", type: "analysis", name: "Desc", parentId: "ex", analysisType: "descriptive-statistics" },
    bare: wandColumnTable("bare", "No children yet"),
    t1: wandColumnTable("t1", "Target"),
  };
  const childOrder = { ex: ["a1"], bare: [], t1: [] };
  deepStrictEqual(
    wandExamples(nodes, childOrder, ["ex", "bare", "t1"], "t1").map((t) => t.id),
    ["ex"],
  );
});

// ── Prism scripts (v2 item 6) ────────────────────────────────────────────

const scriptTable = (): ProjectNode => ({
  id: "t1",
  type: "table",
  name: "Data 1",
  parentId: null,
  tableType: "xy",
  data: {
    columns: ["Title", "X", "Y1", "Y2"],
    rows: [
      ["a", "1", "2", "3"],
      ["b", "2", "4", "5"],
      ["c", "3", "6", "7"],
    ],
  },
});
const scriptGraph = (): ProjectNode => ({
  id: "g1",
  type: "graph",
  name: "Graph 1",
  parentId: "t1",
  graphType: "xy-scatter",
  graphOptions: newGraphOptions("xy-scatter"),
});
const scriptDoc = (extra?: Partial<ScriptDoc>): ScriptDoc => {
  const t1 = scriptTable();
  const g1 = scriptGraph();
  return { nodes: { t1, g1 }, rootOrder: ["t1"], childOrder: { t1: ["g1"] }, activeNodeId: "t1", ...extra };
};
const scriptLog = (result: ReturnType<typeof runScript>) => result.log.join("\n");

/** The first info sheet's constants without their ids (ids are random per
 *  run) — what a script's SetInfo wrote, for the checks to assert on. */
const constantValues = (doc: ScriptDoc) =>
  infoSheetsOf(doc.nodes, doc.rootOrder)[0]?.info?.constants.map(({ name, value, notes }) => ({
    name,
    value,
    ...(notes !== undefined ? { notes } : {}),
  }));

check("script: comments and quoted commas parse; an unknown command names its line and stops the run", () => {
  const okRun = runScript(
    scriptDoc(),
    `// a comment\nSetInfo "a, b", 1\n/* multi\nline */ SetProjectName "Exp 1"`,
  );
  strictEqual(okRun.stopped, false);
  strictEqual(okRun.doc.projectName, "Exp 1");
  // SetInfo wrote into the first info sheet (created by the run).
  deepStrictEqual(constantValues(okRun.doc), [{ name: "", value: "a, b" }]);
  const bad = runScript(scriptDoc(), `SetInfo "x", 1\nNope 2\nSetInfo "y", 2`);
  strictEqual(bad.stopped, true);
  ok(scriptLog(bad).includes('Line 2: unknown command "Nope"'), scriptLog(bad));
  // Atomic: a run that stops changes nothing — no info sheet was created.
  strictEqual(infoSheetsOf(bad.doc.nodes, bad.doc.rootOrder).length, 0);
});

check("script: SetYReplicates regroups a grouped table, replicates an XY table, and warn-skips a Column table", () => {
  const xy = runScript(scriptDoc(), "SetYReplicates 3");
  strictEqual(xy.stopped, false);
  deepStrictEqual(xy.doc.nodes.t1.data!.columns, ["Title", "X", "A:Y1", "A:Y2", "A:Y3", "B:Y1", "B:Y2", "B:Y3"]);
  deepStrictEqual(xy.doc.nodes.t1.data!.rows[0], ["a", "1", "2", null, null, "3", null, null]);
  const grouped = scriptDoc();
  grouped.nodes.t2 = {
    id: "t2",
    type: "table",
    name: "Grouped",
    parentId: null,
    tableType: "grouped",
    data: writeBlock(newGroupedTable(2, 3), 0, 0, [["r1", "a1", "a2", "a3", "b1", "b2", "b3"]], "grouped"),
  };
  grouped.rootOrder = ["t1", "t2"];
  grouped.childOrder.t2 = [];
  const g = runScript(grouped, "GoTo D, 2\nSetYReplicates 2");
  strictEqual(g.stopped, false);
  deepStrictEqual(g.doc.nodes.t2.data!.columns, ["Title", "A:Y1", "A:Y2", "B:Y1", "B:Y2"]);
  deepStrictEqual(g.doc.nodes.t2.data!.rows[0], ["r1", "a1", "a2", "b1", "b2"]);
  const column = scriptDoc();
  column.nodes.t1.tableType = "column";
  column.nodes.t1.data = { columns: ["Title", "A", "B"], rows: [[null, "1", "2"]] };
  const c = runScript(column, "SetYReplicates 3");
  strictEqual(c.stopped, false);
  ok(scriptLog(c).includes("no replicate"), scriptLog(c));
  deepStrictEqual(c.doc.nodes.t1.data!.columns, ["Title", "A", "B"]);
});

check("script: ClearTable with no args erases the whole table but keeps its links", () => {
  const result = runScript(scriptDoc(), "ClearTable");
  strictEqual(result.stopped, false);
  deepStrictEqual(result.doc.nodes.t1.data!.rows, [
    [null, null, null, null],
    [null, null, null, null],
    [null, null, null, null],
  ]);
  // The graph survives: ClearTable keeps links to analyses and graphs.
  ok(result.doc.nodes.g1);
});

check("script: ClearTable with args erases left-and-below the cell only", () => {
  const result = runScript(scriptDoc(), "ClearTable 2, 1");
  strictEqual(result.stopped, false);
  deepStrictEqual(result.doc.nodes.t1.data!.rows, [
    ["a", "1", "2", "3"],
    ["b", null, null, "5"],
    ["c", null, null, "7"],
  ]);
});

check("script: DeleteAllDataSets clears every table and drops its analyses and graphs", () => {
  const doc = scriptDoc();
  doc.nodes.a1 = {
    id: "a1",
    type: "analysis",
    name: "Fit",
    parentId: "t1",
    analysisType: "linear-regression",
    analysisParams: { y: "Y1" },
  };
  doc.childOrder.t1 = ["g1", "a1"];
  const result = runScript(doc, "DeleteAllDataSets");
  strictEqual(result.stopped, false);
  deepStrictEqual(Object.keys(result.doc.nodes), ["t1"]);
  deepStrictEqual(result.doc.nodes.t1.data!.rows, [
    [null, null, null, null],
    [null, null, null, null],
    [null, null, null, null],
  ]);
  deepStrictEqual(result.doc.childOrder, { t1: [] });
});

check("script: SetInfo sets values, names and appends notes; SetValueToInfo copies a cell", () => {
  const result = runScript(
    scriptDoc(),
    `SetInfo "Exp 1", 1\nSetInfo "Assay", 1, 0\nSetInfo "run in triplicate", 1, 2\nSetInfo " on Monday", 1, 2\nSetValueToInfo 1, 2, 1, 1`,
  );
  strictEqual(result.stopped, false);
  deepStrictEqual(constantValues(result.doc), [
    { name: "Assay", value: "Exp 1", notes: "run in triplicate on Monday" },
    { name: "", value: "2" },
  ]);
  const badTable = runScript(scriptDoc(), "SetValueToInfo 2, 1, 1, 1");
  strictEqual(badTable.stopped, true);
  ok(scriptLog(badTable).includes("must be 1, not 2"), scriptLog(badTable));
});

check("script: GoTo moves between sheets and GoTo + steps to the next one", () => {
  const doc = scriptDoc();
  doc.nodes.t2 = {
    id: "t2",
    type: "table",
    name: "Data 2",
    parentId: null,
    tableType: "column",
    data: { columns: ["Title", "A"], rows: [[null, "1"]] },
  };
  doc.rootOrder = ["t1", "t2"];
  doc.childOrder.t2 = [];
  const result = runScript(doc, "GoTo D, 2\nSetSheetTitle Renamed\nGoTo +\nSetSheetTitle First");
  strictEqual(result.stopped, false);
  strictEqual(result.doc.nodes.t2.name, "Renamed");
  // The sheet after Data 2 wraps to the first sheet, Data 1.
  strictEqual(result.doc.nodes.t1.name, "First");
  const bad = runScript(doc, "GoTo G, 5");
  strictEqual(bad.stopped, true);
  ok(scriptLog(bad).includes("graph 5"), scriptLog(bad));
});

check("script: InsertData writes an inline <Data> block at the given position", () => {
  const result = runScript(
    scriptDoc(),
    `InsertData 1, 1, 1\n<Data>\n10, 20\n30, 40\n</Data>`,
  );
  strictEqual(result.stopped, false);
  deepStrictEqual(result.doc.nodes.t1.data!.rows, [
    ["a", "1", "10", "20"],
    ["b", "2", "30", "40"],
    ["c", "3", "6", "7"],
  ]);
  const sameLine = runScript(scriptDoc(), "InsertData 1, 0, 1, <Data>, 9, 8, </Data>");
  strictEqual(sameLine.stopped, false);
  strictEqual(sameLine.doc.nodes.t1.data!.rows[0][1], "9");
  strictEqual(sameLine.doc.nodes.t1.data!.rows[0][2], "8");
  const noBlock = runScript(scriptDoc(), "InsertData 1, 1, 1");
  strictEqual(noBlock.stopped, true);
  ok(scriptLog(noBlock).includes("<Data>"), scriptLog(noBlock));
});

check("script: DuplicateDataTable copies the table without its children", () => {
  const result = runScript(scriptDoc(), "DuplicateDataTable");
  strictEqual(result.stopped, false);
  const copies = Object.values(result.doc.nodes).filter((n) => n.type === "table" && n.id !== "t1");
  strictEqual(copies.length, 1);
  strictEqual(copies[0].name, "Copy of Data 1");
  deepStrictEqual(copies[0].data, scriptTable().data);
  deepStrictEqual(result.doc.rootOrder, ["t1", copies[0].id]);
  deepStrictEqual(result.doc.childOrder[copies[0].id], []);
  // The original keeps its graph; the copy has none.
  deepStrictEqual(result.doc.childOrder.t1, ["g1"]);
});

check("script: ExportTIF validates resolution and mode, and resolves paths through SetPath", () => {
  const badRes = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportTIF "g.tif", 200');
  strictEqual(badRes.stopped, true);
  ok(scriptLog(badRes).includes("200"), scriptLog(badRes));
  const badMode = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportTIF "g.tif", 300, CMYK');
  strictEqual(badMode.stopped, true);
  ok(scriptLog(badMode).includes("CMYK"), scriptLog(badMode));
  const okRun = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportTIF "g.tif", 600, RGBhi');
  strictEqual(okRun.stopped, false);
  deepStrictEqual(okRun.effects, [
    { type: "export-graph", graphId: "g1", format: "tif", dpi: 600, clear: false, mode: "rgbhi", path: "/tmp/out/g.tif" },
  ]);
  const noPath = runScript(scriptDoc(), "GoTo G, 1\nExportTIF");
  strictEqual(noPath.stopped, true);
  ok(scriptLog(noPath).includes("SetPath"), scriptLog(noPath));
});

// Seq 295: ExportPDF / ExportEPS / ExportAllPDF are no longer deferred —
// they wire to the seq 216 writers (vector PDF via svgToPdf, EPS via
// svgToEps). The pure engine pins the effects; the render routing (vector
// PDF/EPS, raster-PDF fallback with a script-log warning, per-sheet batch
// warning) is pinned on the source, as the headless harness has no DOM to
// drive Plotly through — the live Mac re-proof verifies the bytes end to
// end.
check("script: ExportPDF / ExportEPS / ExportAllPDF write vector PDF/EPS through the seq 216 writers (seq 295)", () => {
  // ExportPDF: the current graph, default name under SetPath.
  const pdf = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportPDF');
  strictEqual(pdf.stopped, false, scriptLog(pdf));
  deepStrictEqual(pdf.effects, [
    { type: "export-graph", graphId: "g1", format: "pdf", dpi: 300, clear: false, path: "/tmp/out/Graph 1.pdf" },
  ]);
  const pdfNamed = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportPDF "dose.pdf", 600');
  strictEqual(pdfNamed.stopped, false, scriptLog(pdfNamed));
  deepStrictEqual(pdfNamed.effects, [
    { type: "export-graph", graphId: "g1", format: "pdf", dpi: 600, clear: false, path: "/tmp/out/dose.pdf" },
  ]);
  // The old DEFERRED refusal is gone: without a path it asks for SetPath,
  // not for a PDF writer.
  const pdfNoPath = runScript(scriptDoc(), "GoTo G, 1\nExportPDF");
  strictEqual(pdfNoPath.stopped, true);
  ok(scriptLog(pdfNoPath).includes("SetPath"), scriptLog(pdfNoPath));
  ok(!scriptLog(pdfNoPath).includes("PDF writer"), scriptLog(pdfNoPath));
  const pdfBadRes = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportPDF "g.pdf", 200');
  strictEqual(pdfBadRes.stopped, true);
  ok(scriptLog(pdfBadRes).includes("200"), scriptLog(pdfBadRes));
  const pdfNoGraph = runScript(scriptDoc(), "ExportPDF");
  strictEqual(pdfNoGraph.stopped, true);
  ok(scriptLog(pdfNoGraph).includes("no graph is current"), scriptLog(pdfNoGraph));
  // ExportEPS: the current graph as vector PostScript; a resolution is
  // meaningless for EPS and is ignored with a note, like SVG.
  const eps = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportEPS');
  strictEqual(eps.stopped, false, scriptLog(eps));
  deepStrictEqual(eps.effects, [
    { type: "export-graph", graphId: "g1", format: "eps", dpi: 300, clear: false, path: "/tmp/out/Graph 1.eps" },
  ]);
  const epsRes = runScript(scriptDoc(), 'SetPath "/tmp/out"\nGoTo G, 1\nExportEPS "g.eps", 600');
  strictEqual(epsRes.stopped, false, scriptLog(epsRes));
  ok(scriptLog(epsRes).includes("a resolution doesn't apply to EPS"), scriptLog(epsRes));
  const epsNoPath = runScript(scriptDoc(), "GoTo G, 1\nExportEPS");
  strictEqual(epsNoPath.stopped, true);
  ok(!scriptLog(epsNoPath).includes("PostScript writer"), scriptLog(epsNoPath));
  // ExportAllPDF: one vector PDF per graph and layout, named after the
  // sheet (sanitised), same-named sheets de-duplicated.
  const doc = scriptDoc();
  doc.nodes.g2 = {
    id: "g2",
    type: "graph",
    name: "Dose/Response: A*B",
    parentId: "t1",
    graphType: "xy-scatter",
    graphOptions: newGraphOptions("xy-scatter"),
  };
  doc.nodes.f1 = { id: "f1", type: "figure", name: "Layout 1", parentId: null } as ProjectNode;
  doc.childOrder.t1 = ["g1", "g2"];
  doc.rootOrder = ["t1", "f1"];
  const all = runScript(doc, 'SetPath "/tmp/out"\nExportAllPDF');
  strictEqual(all.stopped, false, scriptLog(all));
  deepStrictEqual(all.effects, [
    { type: "export-graph", graphId: "g1", format: "pdf", dpi: 300, clear: false, path: "/tmp/out/Graph 1.pdf", sheetName: "Graph 1" },
    { type: "export-graph", graphId: "g2", format: "pdf", dpi: 300, clear: false, path: "/tmp/out/Dose-Response- A-B.pdf", sheetName: "Dose/Response: A*B" },
    { type: "export-graph", graphId: "f1", format: "pdf", dpi: 300, clear: false, path: "/tmp/out/Layout 1.pdf", sheetName: "Layout 1" },
  ]);
  const allFolder = runScript(doc, 'SetPath "/tmp/out"\nExportAllPDF "/tmp/batch"');
  strictEqual(allFolder.stopped, false, scriptLog(allFolder));
  ok(allFolder.effects.every((e) => e.type === "export-graph" && e.path.startsWith("/tmp/batch/")));
  const allRelative = runScript(doc, 'SetPath "/tmp/out"\nExportAllPDF "batch"');
  strictEqual(allRelative.stopped, false, scriptLog(allRelative));
  ok(allRelative.effects.every((e) => e.type === "export-graph" && e.path.startsWith("/tmp/out/batch/")));
  // Same-named sheets never overwrite each other's file.
  const dupes = scriptDoc();
  dupes.nodes.g2 = {
    id: "g2",
    type: "graph",
    name: "Graph 1",
    parentId: "t1",
    graphType: "xy-scatter",
    graphOptions: newGraphOptions("xy-scatter"),
  };
  dupes.childOrder.t1 = ["g1", "g2"];
  const dupRun = runScript(dupes, 'SetPath "/tmp/out"\nExportAllPDF');
  strictEqual(dupRun.stopped, false, scriptLog(dupRun));
  deepStrictEqual(
    dupRun.effects.map((e) => (e.type === "export-graph" ? e.path : "")),
    ["/tmp/out/Graph 1.pdf", "/tmp/out/Graph 1 (2).pdf"],
  );
  // No graphs or layouts is a script error, not an empty batch; no folder
  // and no SetPath names SetPath.
  const bare = scriptDoc();
  delete bare.nodes.g1;
  bare.childOrder.t1 = [];
  const none = runScript(bare, 'SetPath "/tmp/out"\nExportAllPDF');
  strictEqual(none.stopped, true);
  ok(scriptLog(none).includes("no graphs or layouts"), scriptLog(none));
  const noFolder = runScript(doc, "ExportAllPDF");
  strictEqual(noFolder.stopped, true);
  ok(scriptLog(noFolder).includes("SetPath"), scriptLog(noFolder));
  // The script-dialog help lists all three commands.
  const help = readFileSync("src/components/script-dialog.tsx", "utf8");
  for (const cmd of ["ExportPDF", "ExportEPS", "ExportAllPDF"]) {
    ok(help.includes(cmd), `script-dialog help must list ${cmd}`);
  }
  // The render path routes PDF through the vector writer with a raster
  // fallback, EPS through the PostScript writer, and reports whether the
  // bytes are vector — so the dialog can warn when a PDF fell back.
  const render = readFileSync("src/views/graphs/script-graph-export.ts", "utf8");
  ok(render.includes("svgToPdf"), "script export must route PDF through svgToPdf");
  ok(render.includes("svgToEps"), "script export must route EPS through svgToEps");
  ok(render.includes("pdfEncode"), "script PDF must fall back to the raster pdfEncode when vector conversion fails");
  ok(/instanceof VectorExportError/.test(render), "the raster fallback must trigger only on a vector-conversion failure");
  ok(render.includes("vector:"), "renderScriptGraph must report whether its bytes are vector");
  // The effect runner warns in the script log when a PDF fell back to
  // raster, and names the sheet when one batch item fails — the batch
  // continues with the other sheets.
  const effects = readFileSync("src/lib/script-effects.ts", "utf8");
  ok(effects.includes("raster PDF"), "a raster-fallback PDF must warn in the script log");
  ok(effects.includes("sheetName"), "a failed batch sheet must be named in the log");
  ok(effects.includes("batch continues"), "a failed batch sheet must not abort the batch");
});

// Mac GUI proof #1 (S1 PARTIAL): ExportTIF/BMP/Table failed live — the
// Tauri write_file allowlist covered only hlx/prism/png/jpg/jpeg/svg, so
// .tif/.bmp/.csv/.txt were refused ("Titer can't access …"). ExportPNG
// worked, isolating it to this allowlist. Same class as the send-office
// .docx/.pptx pin on its own branch.
check("script: the Tauri write path allows .tif/.tiff/.bmp/.csv/.txt script exports", () => {
  const main = readFileSync("src-tauri/src/main.rs", "utf8");
  const allowed = writeFileAllowlist(main);
  ok(allowed !== "", "write_file must gate on a check_extension allowlist");
  for (const ext of ["tif", "tiff", "bmp", "csv", "txt"]) {
    ok(new RegExp(`"${ext}"`).test(allowed), `write_file allowlist must include .${ext}`);
  }
});

// Mac GUI proof #2 (S1): ExportTIF/ExportBMP wrote structurally valid but
// EMPTY images (0×0 TIFF, header-only BMP) while the run log reported
// success. Root cause was in pngToRgba (script-graph-export.ts): it read
// bitmap.width/bitmap.height in the return AFTER bitmap.close() — and a
// closed ImageBitmap reports 0×0 (MDN: "ImageBitmap { width: 0, height: 0 }
// — disposed"). The canvas readback itself used the real dimensions, so
// only the dimensions were lost and the encoders faithfully wrote 0×0.
// The headless harness has no DOM, so it cannot drive the canvas readback
// — this pin guards the ordering and the loud-failure throw in source
// instead; the live Mac re-proof #3 verifies the dimensions end to end.
check("script: pngToRgba reads the bitmap size before close() and fails loud on an empty decode", () => {
  const src = readFileSync("src/views/graphs/script-graph-export.ts", "utf8");
  const fn = /async function pngToRgba[\s\S]*?\n}/.exec(src);
  ok(fn, "pngToRgba must exist in script-graph-export.ts");
  const body = fn![0];
  const closeAt = body.indexOf("bitmap.close()");
  ok(closeAt >= 0, "pngToRgba must close the bitmap");
  ok(body.includes("bitmap.width") && body.includes("bitmap.height"), "pngToRgba must read the bitmap dimensions");
  const afterClose = body.slice(closeAt);
  ok(
    !afterClose.includes("bitmap.width") && !afterClose.includes("bitmap.height"),
    "pngToRgba must not read bitmap.width/height after bitmap.close() — a closed ImageBitmap reports 0×0",
  );
  ok(
    /width <= 0 \|\| height <= 0/.test(body) && /throw new Error/.test(body),
    "pngToRgba must throw instead of encoding a 0×0 decode",
  );
});

