// Seq 427 — .dat/.prn text data files (Prism guide "Importing text and
// Excel files directly": .TXT/.DAT/.CSV/.PRN). A Prism .prn export is a
// tab-delimited text table; a .dat file is the same shape (tab- or
// space-delimited). Both go through the delimited-text parser, never the
// .xlsx one.
check("import-427: .dat and .prn files import as delimited text tables", async () => {
  ok(isDataFilePath("assay.dat") && isDataFilePath("assay.PRN"), ".dat/.prn not recognised as data files");
  const dat = await importTabularFile(
    "assay.dat",
    "Sample\tControl\tTreated\nS1\t1.5\t2.5\nS2\t1.7\t2.9\n",
  );
  strictEqual(dat.tableType, "column");
  deepStrictEqual(dat.data.columns, ["Title", "Control", "Treated"]);
  deepStrictEqual(dat.data.rows, [
    ["S1", "1.5", "2.5"],
    ["S2", "1.7", "2.9"],
  ]);
  const prn = await importTabularFile("assay.prn", "X\tResponse\n0\t1.1\n1\t2.2\n");
  strictEqual(prn.tableType, "xy");
  deepStrictEqual(prn.data.columns, ["Title", "X", "Response"]);
  // The whole import path names the new types: web picker, native panel
  // + text reader, and the MCP import gate.
  const document = readFileSync("src/store/use-document.ts", "utf8");
  ok(document.includes(".dat") && document.includes(".prn"), "web picker accept list misses .dat/.prn");
  const shell = readFileSync("src-tauri/src/main.rs", "utf8");
  ok(shell.includes('"dat"') && shell.includes('"prn"'), "native panel / text reader misses .dat/.prn");
  const dispatch = readFileSync("src/store/mcp-dispatch.ts", "utf8");
  ok(dispatch.includes('ext !== "dat"') && dispatch.includes('ext !== "prn"'), "MCP import gate misses .dat/.prn");
});

// Seq 429 — Prism's Import and Paste Special Choices dialog, 5 tabs
// (walk2/07–11, all five tabs dumped verbatim from real Prism 11.2.0).
// Titer had no import dialog at all; the choices lived nowhere. The pure
// engine is src/lib/import-choices.ts; the dialog is
// src/views/tables/import-dialog.tsx; the store offers the parsed file and
// applies the confirmed choices (use-document.ts).
check("import-429: the 5-tab Import dialog's choices parse, filter and place as Prism's do", () => {
  // The defaults are Prism's as captured: insert data only (no link),
  // commas separate columns, spaces only in headings/X labels, asterisk
  // exclusion on, rows/columns 1..last, rename with the file name,
  // insertion at the live insertion point, arrangement maintained, blank
  // rows left, no info/notes import.
  const defaults = defaultImportChoices();
  deepStrictEqual(defaults, {
    source: { link: false, autoUpdate: true, comma: "separate", spaces: "headings" },
    filter: {
      missingMarker: "",
      excludeAsterisks: true,
      startRow: 1,
      endRow: "last",
      skipUntil: null,
      skipAfter: null,
      skipWhere: null,
      decimate: 0,
      startCol: 1,
      endCol: "last",
      unstack: null,
      skipColumns: 0,
    },
    placement: {
      rename: true,
      renameFrom: "file",
      renameRow: 1,
      target: "insert",
      useLiveInsertionPoint: true,
      insertRow: 1,
      insertCol: 1,
      arrangement: "maintain",
      byRowsRows: 1,
      byColumnsValues: 1,
      blankRows: "leave",
      columnTitles: "auto",
    },
    info: {
      infoMode: "none",
      infoFromRow: 1,
      infoEndRow: "last",
      notesMode: "none",
      notesFromRow: 1,
      notesEndRow: "last",
    },
  });
  deepStrictEqual(IMPORT_CHOICE_TABS, ["Source", "View", "Filter", "Placement", "Info & Notes"]);

  // Source — commas: separate splits them; thousands joins "100,000" into
  // one hundred thousand (only when the delimiter isn't a comma — a
  // comma-delimited file's commas are separators by definition); decimal
  // reads "100,000" as 100.000.
  const withComma = (comma: ImportChoices["source"]["comma"]): ImportChoices => ({
    ...defaults,
    source: { ...defaults.source, comma },
  });
  deepStrictEqual(parseImportText("A,100,000\nB,200,000", "csv", withComma("separate")), [
    ["A", "100", "000"],
    ["B", "200", "000"],
  ]);
  deepStrictEqual(parseImportText("A\t100,000\nB\t200,000", "txt", withComma("thousands")), [
    ["A", "100000"],
    ["B", "200000"],
  ]);
  deepStrictEqual(parseImportText("A\t100,000\nB\t200,000", "txt", withComma("decimal")), [
    ["A", "100.000"],
    ["B", "200.000"],
  ]);
  // Decimal commas in scientific notation convert too (Issue 56).
  deepStrictEqual(parseImportText("A\t1,5e-3\nB\t4,096e+007", "txt", withComma("decimal")), [
    ["A", "1.5e-3"],
    ["B", "4.096e+007"],
  ]);
  // Source — spaces: "headings" keeps "A 1.5" one field; "separate" splits
  // on runs of spaces (quoted fields keep theirs).
  const withSpaces = (spaces: ImportChoices["source"]["spaces"]): ImportChoices => ({
    ...defaults,
    source: { ...defaults.source, spaces },
  });
  deepStrictEqual(parseImportText('Group Value\nA 1.5\n"New York" 2.5', "txt", withSpaces("headings")), [
    ["Group Value"],
    ["A 1.5"],
    ["New York 2.5"],
  ]);
  deepStrictEqual(parseImportText('Group Value\nA 1.5\n"New York" 2.5', "txt", withSpaces("separate")), [
    ["Group", "Value"],
    ["A", "1.5"],
    ["New York", "2.5"],
  ]);

  // Info & Notes — <Info>/<Notes> sections come out before the data, and
  // the data rows keep nothing of them; "none" passes the file through.
  const sectioned = [
    ["<Info>"],
    ["Date", "2026-01-09"],
    ["Operator", "Smit"],
    ["</Info>"],
    ["<Notes>"],
    ["Run 3, check baseline"],
    ["</Notes>"],
    ["Group", "Value"],
    ["A", "1.5"],
  ];
  deepStrictEqual(extractInfoSections(sectioned, { ...defaults, info: { ...defaults.info, infoMode: "section", notesMode: "section" } }), {
    dataRows: [
      ["Group", "Value"],
      ["A", "1.5"],
    ],
    infoRows: [
      ["Date", "2026-01-09"],
      ["Operator", "Smit"],
    ],
    notesRows: [["Run 3, check baseline"]],
  });
  deepStrictEqual(extractInfoSections(sectioned, defaults).dataRows, sectioned);

  // Filter — the missing-value marker blanks its cells; asterisked values
  // are excluded; row/column ranges slice; skip-where drops its rows;
  // decimate keeps every (N+1)th row; unstack turns long data wide;
  // skip-columns keeps every (N+1)th column.
  const withFilter = (filter: Partial<ImportChoices["filter"]>): ImportChoices => ({
    ...defaults,
    filter: { ...defaults.filter, ...filter },
  });
  deepStrictEqual(
    applyImportFilter(
      [
        ["A", "99"],
        ["B", "45.6*"],
        ["C", "*2.5"],
        ["D", "3.5"],
      ],
      withFilter({ missingMarker: "99" }),
    ).rows,
    [
      ["A", ""],
      ["B", ""],
      ["C", ""],
      ["D", "3.5"],
    ],
  );
  deepStrictEqual(
    applyImportFilter(
      [
        ["A", "1"],
        ["B", "2"],
        ["C", "3"],
        ["D", "4"],
      ],
      withFilter({ startRow: 2, endRow: 3 }),
    ).rows,
    [
      ["B", "2"],
      ["C", "3"],
    ],
  );
  deepStrictEqual(
    applyImportFilter(
      [
        ["A", "1"],
        ["B", "2"],
        ["C", "3"],
      ],
      withFilter({ skipWhere: { col: 2, op: ">", value: "2" } }),
    ).rows,
    [
      ["A", "1"],
      ["B", "2"],
    ],
  );
  deepStrictEqual(
    applyImportFilter([["A"], ["B"], ["C"], ["D"], ["E"]], withFilter({ decimate: 1 })).rows,
    [["A"], ["C"], ["E"]],
  );
  deepStrictEqual(
    applyImportFilter([["a", "b", "c", "d"]], withFilter({ startCol: 2, endCol: 3 })).rows,
    [["b", "c"]],
  );
  deepStrictEqual(
    applyImportFilter(
      [
        ["G", "1"],
        ["G", "2"],
        ["H", "3"],
        ["G", "4"],
        ["H", "5"],
      ],
      withFilter({ unstack: { dataCol: 2, groupCol: 1 } }),
    ).rows,
    [
      ["G", "H"],
      ["1", "3"],
      ["2", "5"],
      ["4", ""],
    ],
  );
  deepStrictEqual(applyImportFilter([["a", "b", "c", "d", "e"]], withFilter({ skipColumns: 1 })).rows, [
    ["a", "c", "e"],
  ]);

  // Placement — transpose swaps rows and columns; by-rows fills N values
  // per new column reading across rows; by-columns stacks N values per
  // column reading down them; blank rows are left or skipped.
  const withPlacement = (placement: Partial<ImportChoices["placement"]>): ImportChoices => ({
    ...defaults,
    placement: { ...defaults.placement, ...placement },
  });
  deepStrictEqual(
    applyImportPlacement(
      [
        ["a", "b"],
        ["c", "d"],
      ],
      withPlacement({ arrangement: "transpose" }),
    ).rows,
    [
      ["a", "c"],
      ["b", "d"],
    ],
  );
  deepStrictEqual(
    applyImportPlacement([["a"], ["b"], ["c"], ["d"]], withPlacement({ arrangement: "byRows", byRowsRows: 2 })).rows,
    [
      ["a", "c"],
      ["b", "d"],
    ],
  );
  deepStrictEqual(
    applyImportPlacement(
      [
        ["a", "b"],
        ["c", "d"],
        ["e", "f"],
      ],
      withPlacement({ arrangement: "byColumns", byColumnsValues: 2 }),
    ).rows,
    [
      ["a", "e", "d"],
      ["c", "b", "f"],
    ],
  );
  deepStrictEqual(
    applyImportPlacement(
      [
        ["a", ""],
        ["", ""],
        ["b", ""],
      ],
      withPlacement({ blankRows: "skip" }),
    ).rows,
    [
      ["a", ""],
      ["b", ""],
    ],
  );

  // The whole pipeline: a messy file parses, loses its info section, drops
  // its missing marker, and lands transposed with a note saying so.
  const offer: ImportOffer = {
    name: "import-test.csv",
    path: "/tmp/import-test.csv",
    text: "<Info>\nDate,2026-01-09\n</Info>\nGroup,Value\nA,99\nB,2.5\n",
    xlsxRows: null,
    sheetName: null,
    otherSheets: [],
  };
  const piped = computeImport(offer, {
    ...defaults,
    info: { ...defaults.info, infoMode: "section" },
    filter: { ...defaults.filter, missingMarker: "99" },
    placement: { ...defaults.placement, arrangement: "transpose" },
  });
  deepStrictEqual(piped.rows, [
    ["Group", "A", "B"],
    ["Value", "", "2.5"],
  ]);
  deepStrictEqual(piped.infoConstants, [{ name: "Date", value: "2026-01-09" }]);
  strictEqual(piped.notesText, "");

  // Placement — the table name: the file name, or the text of the chosen
  // row, or nothing when renaming is off (the caller keeps its own name).
  strictEqual(resolveImportTableName(defaults, "import-test.csv", [["Group", "Value"]]), "import-test");
  strictEqual(
    resolveImportTableName(
      { ...defaults, placement: { ...defaults.placement, renameFrom: "row", renameRow: 1 } },
      "import-test.csv",
      [["Dose response", ""], ["A", "1.5"]],
    ),
    "Dose response",
  );
  strictEqual(
    resolveImportTableName(
      { ...defaults, placement: { ...defaults.placement, rename: false } },
      "import-test.csv",
      [["Group", "Value"]],
    ),
    "",
  );

  // Column letters: A is the first data column, AA the 27th.
  strictEqual(dataColumnLetter(0), "A");
  strictEqual(dataColumnLetter(25), "Z");
  strictEqual(dataColumnLetter(26), "AA");
  strictEqual(dataColumnIndex("A"), 0);
  strictEqual(dataColumnIndex("AA"), 26);
  strictEqual(dataColumnIndex("1"), -1);

  // The dialog itself carries all five tabs, worded as Prism words them.
  const dialog = readFileSync("src/views/tables/import-dialog.tsx", "utf8");
  for (const tab of IMPORT_CHOICE_TABS) ok(dialog.includes(`"${tab}"`), `Import dialog misses the ${tab} tab`);
  for (const label of [
    "Insert data only.",
    "Insert and maintain link.",
    "Automatically update Prism when the data file is changed.",
    "To separate adjacent columns",
    "To delineate thousands",
    "As decimal place",
    "Only separate words within column heading and X labels.",
    "Separate adjacent columns.",
    "Missing values are denoted by",
    "Exclude values preceded or followed by asterisks",
    "Decimate: Import a row, skip",
    "Unstack. Column #",
    "Skip columns. Import a column, skip",
    "Rename data table, using",
    "Imported file name",
    "Text in row",
    "The current position of the insertion point",
    "Maintain row and column arrangement of the data source.",
    "Transpose. Each row becomes a column.",
    "By rows. Place",
    "By columns. Stack",
    "Leave a blank row in Prism",
    "Skip over that row",
    "Don't import info constants.",
    "Don't import notes.",
    "Import from portion of file between <Info> and </Info>.",
    "Use these settings as the default for Import and Paste Special.",
    "Restore original defaults",
  ]) {
    ok(dialog.includes(label), `Import dialog misses Prism's wording: ${label}`);
  }
  // And the store offers the parsed file to it, then applies the confirmed
  // choices; the grid shows it over the live insertion point, the shell
  // when no table is active.
  const document = readFileSync("src/store/use-document.ts", "utf8");
  ok(document.includes("pendingImport"), "use-document never offers the parsed file to the dialog");
  ok(document.includes("confirmImport"), "use-document never applies the confirmed import choices");
  ok(document.includes("computeImport"), "use-document never runs the choices pipeline");
  const grid = readFileSync("src/views/tables/grid.tsx", "utf8");
  ok(grid.includes("ImportDialog"), "the grid never shows the Import dialog");
  const shell = readFileSync("src/components/app-shell.tsx", "utf8");
  ok(shell.includes("ImportDialog"), "the shell never shows the Import dialog when no table is active");
});

// ── 1.8 seq 226: automatic backup ────────────────────────────────────────
// Prism (FAQ 1520 + Prism 11 user guide, "Automatic back up of Prism
// files"): backups are SEPARATE copies — written on a timer and/or on
// sheet switch, also on save so a backup is never older than the project
// file; deleted on normal quit; on a crash they remain and Prism reloads
// them on restart; kept 4 days if the original was unsaved. 1.7.3 autosave
// is the other half (it saves in place, only for projects with a target,
// never for untitled work) — backup is the half that covers untitled work
// and crash recovery.
check("seq 226: automatic backup defaults to on, every 10 minutes, on sheet switch", () => {
  const stored: Record<string, string> = {};
  const storage = {
    getItem: (k: string) => stored[k] ?? null,
    setItem: (k: string, v: string) => void (stored[k] = v),
  };
  Object.assign(globalThis, { localStorage: storage });
  try {
    strictEqual(isBackupEnabled(), true, "backup should default on");
    strictEqual(backupIntervalMinutes(), BACKUP_DEFAULT_INTERVAL_MINUTES, "interval should default to 10 minutes");
    strictEqual(BACKUP_DEFAULT_INTERVAL_MINUTES, 10, "the default interval is Prism's 10 minutes");
    strictEqual(BACKUP_MIN_INTERVAL_MINUTES, 1, "the shortest interval is 1 minute");
    strictEqual(BACKUP_MAX_INTERVAL_MINUTES, 60, "the longest interval is 60 minutes");
    strictEqual(isBackupOnSheetSwitch(), true, "backup on sheet switch should default on");
    strictEqual(BACKUP_RETENTION_DAYS, 4, "backups are kept 4 days, like Prism 10+");
  } finally {
    delete (globalThis as { localStorage?: unknown }).localStorage;
  }
  // No localStorage under Node: reads as the defaults, never throws.
  strictEqual(isBackupEnabled(), true, "no storage should read as backup on");
  strictEqual(backupIntervalMinutes(), 10, "no storage should read as 10 minutes");
  strictEqual(isBackupOnSheetSwitch(), true, "no storage should read as sheet-switch backup on");
});

check("seq 226: backup settings round-trip and clamp", () => {
  const stored: Record<string, string> = {};
  const storage = {
    getItem: (k: string) => stored[k] ?? null,
    setItem: (k: string, v: string) => void (stored[k] = v),
  };
  Object.assign(globalThis, { localStorage: storage });
  try {
    setBackupEnabled(false);
    strictEqual(isBackupEnabled(), false, "disabling backup should stick");
    setBackupEnabled(true);
    strictEqual(isBackupEnabled(), true, "re-enabling backup should stick");
    setBackupIntervalMinutes(0);
    strictEqual(backupIntervalMinutes(), 1, "0 minutes should clamp to the 1-minute minimum");
    setBackupIntervalMinutes(120);
    strictEqual(backupIntervalMinutes(), 60, "120 minutes should clamp to the 60-minute maximum");
    setBackupIntervalMinutes(5);
    strictEqual(backupIntervalMinutes(), 5, "5 minutes should stick");
    setBackupIntervalMinutes(Number.NaN);
    strictEqual(backupIntervalMinutes(), 10, "a non-number interval should fall back to the default");
    setBackupOnSheetSwitch(false);
    strictEqual(isBackupOnSheetSwitch(), false, "disabling sheet-switch backup should stick");
    setBackupOnSheetSwitch(true);
    strictEqual(isBackupOnSheetSwitch(), true, "re-enabling sheet-switch backup should stick");
  } finally {
    delete (globalThis as { localStorage?: unknown }).localStorage;
  }
});

check("seq 226: backup identities distinguish projects and stay stable", () => {
  const fileA = backupIdentity({ filePath: "/Research/Dose Response.hlx" });
  const fileB = backupIdentity({ filePath: "/Research/Other.hlx" });
  ok(fileA !== fileB, "two files should get different backup identities");
  strictEqual(backupIdentity({ filePath: "/Research/Dose Response.hlx" }), fileA, "the same file should keep its identity");
  const remote = backupIdentity({ remote: { provider: "box", accountId: "u1", fileId: "123", path: "/Research/Data.hlx" } });
  ok(remote !== fileA, "a cloud file should not share a local file's identity");
  ok(
    backupIdentity({ remote: { provider: "box", accountId: "u1", fileId: "124", path: "/Research/Data.hlx" } }) !== remote,
    "two cloud files with the same path but different ids should differ",
  );
  strictEqual(backupDisplayName({ filePath: "/Research/Dose Response.hlx" }), "Dose Response.hlx", "a file backup shows its file name");
  strictEqual(
    backupDisplayName({ remote: { provider: "box", accountId: "u1", fileId: "123", path: "/Research/Data.hlx" } }),
    "Data.hlx",
    "a cloud backup shows its file name",
  );
  strictEqual(backupDisplayName({ untitledId: "abc123", untitledName: "Untitled" }), "Untitled", "an untitled backup shows its name");
  // An untitled project's id is stable per window label across calls (so a
  // crash leftover is found again on relaunch) and distinct per label.
  const stored: Record<string, string> = {};
  const storage = {
    getItem: (k: string) => stored[k] ?? null,
    setItem: (k: string, v: string) => void (stored[k] = v),
  };
  Object.assign(globalThis, { localStorage: storage });
  try {
    const first = untitledBackupId("project-1");
    strictEqual(untitledBackupId("project-1"), first, "the same window label should keep its untitled id");
    ok(untitledBackupId("project-2") !== first, "two windows should get different untitled ids");
    ok(!untitledBackupId("project-1").includes("/"), "an untitled id should never hold a path separator");
    clearUntitledBackupId("project-1");
    ok(untitledBackupId("project-1") !== first, "clearing the id should mint a fresh one");
  } finally {
    delete (globalThis as { localStorage?: unknown }).localStorage;
  }
  // No localStorage under Node: the id is still stable within the session.
  ok(untitledBackupId("project-9").length > 0, "no storage should still mint an untitled id");
});

check("seq 226: a backup is offered only when it is newer than the saved file", () => {
  ok(backupIsNewerThanSource(2000, null), "an untitled backup has no saved file to be older than");
  ok(backupIsNewerThanSource(2000, 1000), "a backup written after the last save is newer");
  ok(!backupIsNewerThanSource(1000, 1000), "a backup from the same moment as the save is not newer");
  ok(!backupIsNewerThanSource(1000, 2000), "a backup older than the saved file must never be offered — restoring it would regress the file");
});

